-- ai_agent
CREATE TABLE IF NOT EXISTS "ai_agent" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "agent_name" varchar(100) NOT NULL,
  "agent_code" varchar(50) NOT NULL,
  "description" varchar(500) DEFAULT NULL,
  "system_prompt" text NOT NULL,
  "provider_id" bigint DEFAULT NULL,
  "model_name" varchar(100) DEFAULT NULL,
  "model_selection_mode" varchar(16) NOT NULL DEFAULT 'PINNED',
  "route_policy_id" bigint DEFAULT NULL,
  "temperature" numeric(3,2) DEFAULT 0.70,
  "max_tokens" integer DEFAULT 4000,
  "extra_config" text DEFAULT NULL,
  "greeting" varchar(500) DEFAULT NULL,
  "preset_questions" text,
  "max_iters" integer DEFAULT 10,
  "knowledge_ids" text,
  "rag_mode" varchar(32) DEFAULT 'none',
  "tool_group_mode" varchar(32) DEFAULT 'all',
  "asr_model_id" bigint DEFAULT NULL,
  "tts_model_id" bigint DEFAULT NULL,
  "status" char(1) NOT NULL DEFAULT '0',
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_dept" varchar(30) DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_agent" IS 'AI Agent配置表';
COMMENT ON COLUMN "ai_agent"."id" IS '主键ID';
COMMENT ON COLUMN "ai_agent"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_agent"."agent_name" IS 'Agent名称';
COMMENT ON COLUMN "ai_agent"."agent_code" IS 'Agent编码（唯一）';
COMMENT ON COLUMN "ai_agent"."description" IS '描述';
COMMENT ON COLUMN "ai_agent"."system_prompt" IS '系统提示词模板';
COMMENT ON COLUMN "ai_agent"."provider_id" IS '关联供应商ID';
COMMENT ON COLUMN "ai_agent"."model_name" IS '使用的模型';
COMMENT ON COLUMN "ai_agent"."model_selection_mode" IS '模型选择模式（PINNED/POLICY）';
COMMENT ON COLUMN "ai_agent"."route_policy_id" IS '模型路由策略ID';
COMMENT ON COLUMN "ai_agent"."temperature" IS '温度参数（0-1）';
COMMENT ON COLUMN "ai_agent"."max_tokens" IS '最大Token数';
COMMENT ON COLUMN "ai_agent"."extra_config" IS '扩展配置';
COMMENT ON COLUMN "ai_agent"."greeting" IS '问候语';
COMMENT ON COLUMN "ai_agent"."preset_questions" IS '预设问题JSON数组';
COMMENT ON COLUMN "ai_agent"."max_iters" IS 'ReAct最大轮次';
COMMENT ON COLUMN "ai_agent"."knowledge_ids" IS '关联知识库ID列表JSON';
COMMENT ON COLUMN "ai_agent"."rag_mode" IS 'RAG模式(none/forced/smart)';
COMMENT ON COLUMN "ai_agent"."tool_group_mode" IS '工具组模式(all/skill)';
COMMENT ON COLUMN "ai_agent"."asr_model_id" IS '语音识别模型ID';
COMMENT ON COLUMN "ai_agent"."tts_model_id" IS '语音合成模型ID';
COMMENT ON COLUMN "ai_agent"."status" IS '状态（0正常 1停用）';
COMMENT ON COLUMN "ai_agent"."create_by" IS '创建者';
COMMENT ON COLUMN "ai_agent"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_agent"."update_by" IS '更新者';
COMMENT ON COLUMN "ai_agent"."update_time" IS '更新时间';
COMMENT ON COLUMN "ai_agent"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "ai_agent_uk_agent_code_active" ON "ai_agent" ("agent_code", "del_flag");
CREATE INDEX "ai_agent_idx_tenant_id" ON "ai_agent" ("tenant_id");

