SELECT CASE
  WHEN (SELECT MAX("id") FROM "ai_agent") IS NULL
    THEN setval(pg_get_serial_sequence('ai_agent', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('ai_agent', 'id'),
              (SELECT MAX("id") FROM "ai_agent"), true)
END;

