-- ai_agent_event
CREATE TABLE IF NOT EXISTS "ai_agent_event" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL,
  "session_id" varchar(64) NOT NULL,
  "turn_index" integer NOT NULL,
  "event_type" varchar(50) NOT NULL,
  "event_data" text,
  "parent_id" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_agent_event" IS 'Agent事件流(全量持久化)';
COMMENT ON COLUMN "ai_agent_event"."id" IS '主键';
COMMENT ON COLUMN "ai_agent_event"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_agent_event"."session_id" IS '会话ID';
COMMENT ON COLUMN "ai_agent_event"."turn_index" IS 'ReAct轮次';
COMMENT ON COLUMN "ai_agent_event"."event_type" IS '事件类型(28种)';
COMMENT ON COLUMN "ai_agent_event"."event_data" IS '事件数据JSON';
COMMENT ON COLUMN "ai_agent_event"."parent_id" IS '父事件ID(工具结果关联工具调用)';
CREATE INDEX "ai_agent_event_idx_session" ON "ai_agent_event" ("session_id", "turn_index");
CREATE INDEX "ai_agent_event_idx_session_type" ON "ai_agent_event" ("session_id", "event_type");

