--
-- Table structure for table `ai_business_application`
--
-- ai_business_application
CREATE TABLE IF NOT EXISTS "ai_business_application" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "application_code" varchar(128) NOT NULL,
  "portal_slug" varchar(50) DEFAULT NULL,
  "application_name" varchar(128) NOT NULL,
  "suite_code" varchar(128) NOT NULL,
  "icon" varchar(255) DEFAULT NULL,
  "description" varchar(500) DEFAULT NULL,
  "status" smallint NOT NULL DEFAULT 1,
  "design_status" varchar(32) NOT NULL DEFAULT 'DRAFT',
  "last_publish_version" integer DEFAULT NULL,
  "last_publish_time" timestamp DEFAULT NULL,
  "options" text DEFAULT NULL,
  "portal_config" text DEFAULT NULL,
  "ai_assistant_config" text DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_application" IS '低代码业务应用聚合';
COMMENT ON COLUMN "ai_business_application"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_application"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_application"."application_code" IS '业务应用编码';
COMMENT ON COLUMN "ai_business_application"."portal_slug" IS '门户访问 slug';
COMMENT ON COLUMN "ai_business_application"."application_name" IS '业务应用名称';
COMMENT ON COLUMN "ai_business_application"."suite_code" IS '所属业务域编码';
COMMENT ON COLUMN "ai_business_application"."icon" IS '应用图标';
COMMENT ON COLUMN "ai_business_application"."description" IS '应用说明';
COMMENT ON COLUMN "ai_business_application"."status" IS '状态：1启用 0禁用';
COMMENT ON COLUMN "ai_business_application"."design_status" IS '设计状态：DRAFT/READY/PUBLISHED/CHANGED';
COMMENT ON COLUMN "ai_business_application"."last_publish_version" IS '最近发布版本号';
COMMENT ON COLUMN "ai_business_application"."last_publish_time" IS '最近发布时间';
COMMENT ON COLUMN "ai_business_application"."options" IS '扩展配置，不保存敏感密钥';
COMMENT ON COLUMN "ai_business_application"."portal_config" IS '门户主题、水印和导航配置';
COMMENT ON COLUMN "ai_business_application"."ai_assistant_config" IS '应用 AI 助理绑定配置';
