-- ai_business_application_object
CREATE TABLE IF NOT EXISTS "ai_business_application_object" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "application_id" bigint NOT NULL,
  "object_id" bigint NOT NULL,
  "object_role" varchar(32) NOT NULL,
  "sort_order" integer NOT NULL DEFAULT 0,
  "options" text DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_application_object" IS '业务应用与业务对象关联';
COMMENT ON COLUMN "ai_business_application_object"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_application_object"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_application_object"."application_id" IS '业务应用ID';
COMMENT ON COLUMN "ai_business_application_object"."object_id" IS '业务对象ID';
COMMENT ON COLUMN "ai_business_application_object"."object_role" IS '对象角色：PRIMARY/DETAIL/REFERENCE/SHARED';
COMMENT ON COLUMN "ai_business_application_object"."sort_order" IS '应用内排序';
COMMENT ON COLUMN "ai_business_application_object"."options" IS '应用内对象配置';
COMMENT ON COLUMN "ai_business_application_object"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
COMMENT ON COLUMN "ai_business_application_object"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_application_object"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_application_object"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_application_object"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_application_object"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_business_application_object_uk_ai_business_applicat_f4f35d34" ON "ai_business_application_object" ("tenant_id", "application_id", "object_id", "del_flag");
CREATE INDEX "ai_business_application_object_idx_ai_business_applica_7a177f00" ON "ai_business_application_object" ("tenant_id", "application_id", "object_role", "sort_order", "del_flag");
