--
-- Table structure for table `ai_business_application_publish_run`
--
-- ai_business_application_publish_run
CREATE TABLE IF NOT EXISTS "ai_business_application_publish_run" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "application_id" bigint NOT NULL,
  "idempotency_key" varchar(128) NOT NULL,
  "operation_type" varchar(16) NOT NULL DEFAULT 'PUBLISH',
  "target_version_no" integer NOT NULL,
  "source_version_no" integer DEFAULT NULL,
  "run_status" varchar(24) NOT NULL DEFAULT 'CREATED',
  "current_step" varchar(32) DEFAULT NULL,
  "snapshot_json" text NOT NULL,
  "snapshot_hash" char(64) NOT NULL,
  "selection_json" text NOT NULL,
  "step_results_json" text NOT NULL,
  "result_version_id" bigint DEFAULT NULL,
  "error_code" varchar(64) DEFAULT NULL,
  "error_summary" varchar(500) DEFAULT NULL,
  "attempt_count" integer NOT NULL DEFAULT 1,
  "started_by" bigint DEFAULT NULL,
  "started_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "finished_time" timestamp DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_application_publish_run" IS '低代码业务应用协调发布运行单';
COMMENT ON COLUMN "ai_business_application_publish_run"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_application_publish_run"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_application_publish_run"."application_id" IS '业务应用ID';
COMMENT ON COLUMN "ai_business_application_publish_run"."idempotency_key" IS '应用内发布幂等键';
COMMENT ON COLUMN "ai_business_application_publish_run"."operation_type" IS 'PUBLISH/ROLLBACK';
COMMENT ON COLUMN "ai_business_application_publish_run"."target_version_no" IS '本次发布目标版本号';
COMMENT ON COLUMN "ai_business_application_publish_run"."source_version_no" IS '回滚来源版本号';
COMMENT ON COLUMN "ai_business_application_publish_run"."run_status" IS 'CREATED/RUNNING/PARTIAL/FAILED/SUCCESS';
COMMENT ON COLUMN "ai_business_application_publish_run"."current_step" IS '当前或失败步骤';
COMMENT ON COLUMN "ai_business_application_publish_run"."snapshot_json" IS '候选发布快照，不保存密钥';
COMMENT ON COLUMN "ai_business_application_publish_run"."snapshot_hash" IS '候选快照SHA-256摘要';
COMMENT ON COLUMN "ai_business_application_publish_run"."selection_json" IS '本次选择及自动补齐的依赖资产';
COMMENT ON COLUMN "ai_business_application_publish_run"."step_results_json" IS '可恢复步骤结果，不保存原始异常';
COMMENT ON COLUMN "ai_business_application_publish_run"."result_version_id" IS '成功生成的不可变应用版本ID';
COMMENT ON COLUMN "ai_business_application_publish_run"."error_code" IS '脱敏错误码';
COMMENT ON COLUMN "ai_business_application_publish_run"."error_summary" IS '脱敏错误摘要';
COMMENT ON COLUMN "ai_business_application_publish_run"."attempt_count" IS '发布或恢复尝试次数';
COMMENT ON COLUMN "ai_business_application_publish_run"."started_by" IS '可信发起人ID';
COMMENT ON COLUMN "ai_business_application_publish_run"."started_time" IS '首次发起时间';
COMMENT ON COLUMN "ai_business_application_publish_run"."finished_time" IS '完成或最近失败时间';
COMMENT ON COLUMN "ai_business_application_publish_run"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
COMMENT ON COLUMN "ai_business_application_publish_run"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_application_publish_run"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_application_publish_run"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_application_publish_run"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_application_publish_run"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_business_application_publish_run_uk_ai_business_pub_40920c63" ON "ai_business_application_publish_run" ("tenant_id", "application_id", "idempotency_key", "del_flag");
CREATE UNIQUE INDEX "ai_business_application_publish_run_uk_ai_business_pub_2099b182" ON "ai_business_application_publish_run" ("tenant_id", "application_id", "target_version_no", "del_flag");
CREATE INDEX "ai_business_application_publish_run_idx_ai_business_pu_c4fac916" ON "ai_business_application_publish_run" ("tenant_id", "application_id", "run_status", "update_time", "del_flag");

