--
-- Table structure for table `ai_business_application_version`
--
-- ai_business_application_version
CREATE TABLE IF NOT EXISTS "ai_business_application_version" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "application_id" bigint NOT NULL,
  "version_no" integer NOT NULL,
  "snapshot_json" text NOT NULL,
  "snapshot_hash" char(64) NOT NULL,
  "publish_status" varchar(24) NOT NULL,
  "publish_summary" varchar(1000) DEFAULT NULL,
  "source_version_no" integer DEFAULT NULL,
  "published_by" bigint DEFAULT NULL,
  "published_time" timestamp NOT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_application_version" IS '低代码业务应用不可变发布版本';
COMMENT ON COLUMN "ai_business_application_version"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_application_version"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_application_version"."application_id" IS '业务应用ID';
COMMENT ON COLUMN "ai_business_application_version"."version_no" IS '应用内单调版本号';
COMMENT ON COLUMN "ai_business_application_version"."snapshot_json" IS '不可变应用发布快照，不保存密钥';
COMMENT ON COLUMN "ai_business_application_version"."snapshot_hash" IS '快照SHA-256摘要';
COMMENT ON COLUMN "ai_business_application_version"."publish_status" IS 'PUBLISHED/ROLLBACK';
COMMENT ON COLUMN "ai_business_application_version"."publish_summary" IS '脱敏发布摘要';
COMMENT ON COLUMN "ai_business_application_version"."source_version_no" IS '回滚来源版本号';
COMMENT ON COLUMN "ai_business_application_version"."published_by" IS '可信发布人ID';
COMMENT ON COLUMN "ai_business_application_version"."published_time" IS '发布时间';
COMMENT ON COLUMN "ai_business_application_version"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
COMMENT ON COLUMN "ai_business_application_version"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_application_version"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_application_version"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_application_version"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_application_version"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_business_application_version_uk_ai_business_applica_f7e727f5" ON "ai_business_application_version" ("tenant_id", "application_id", "version_no", "del_flag");
CREATE INDEX "ai_business_application_version_idx_ai_business_applic_1b5597ad" ON "ai_business_application_version" ("tenant_id", "application_id", "snapshot_hash", "del_flag");
CREATE INDEX "ai_business_application_version_idx_ai_business_applic_a5e76c81" ON "ai_business_application_version" ("tenant_id", "application_id", "published_time", "del_flag");

