--
-- Table structure for table `ai_business_document_config`
--
-- ai_business_document_config
CREATE TABLE IF NOT EXISTS "ai_business_document_config" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "object_id" bigint DEFAULT NULL,
  "suite_code" varchar(48) NOT NULL,
  "object_code" varchar(48) NOT NULL,
  "config_key" varchar(128) DEFAULT NULL,
  "document_name" varchar(128) NOT NULL,
  "document_no_rule" varchar(256) DEFAULT NULL,
  "document_enabled" smallint NOT NULL DEFAULT 0,
  "status_field" varchar(64) DEFAULT NULL,
  "starter_field" varchar(64) DEFAULT NULL,
  "owner_field" varchar(64) DEFAULT NULL,
  "default_flow_key" varchar(128) DEFAULT NULL,
  "status_mapping" text DEFAULT NULL,
  "options" text DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_document_config" IS 'AI业务应用平台-业务单据配置表';
COMMENT ON COLUMN "ai_business_document_config"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_document_config"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_document_config"."object_id" IS '业务对象ID';
COMMENT ON COLUMN "ai_business_document_config"."suite_code" IS '业务套件编码';
COMMENT ON COLUMN "ai_business_document_config"."object_code" IS '业务对象编码';
COMMENT ON COLUMN "ai_business_document_config"."config_key" IS '动态CRUD运行配置键';
COMMENT ON COLUMN "ai_business_document_config"."document_name" IS '单据名称';
COMMENT ON COLUMN "ai_business_document_config"."document_no_rule" IS '单据编号规则';
COMMENT ON COLUMN "ai_business_document_config"."document_enabled" IS '是否启用单据模式';
COMMENT ON COLUMN "ai_business_document_config"."status_field" IS '单据状态字段';
COMMENT ON COLUMN "ai_business_document_config"."starter_field" IS '发起人字段';
COMMENT ON COLUMN "ai_business_document_config"."owner_field" IS '负责人字段';
COMMENT ON COLUMN "ai_business_document_config"."default_flow_key" IS '默认流程模型Key';
COMMENT ON COLUMN "ai_business_document_config"."status_mapping" IS '单据状态映射JSON';
COMMENT ON COLUMN "ai_business_document_config"."options" IS '扩展配置JSON';
COMMENT ON COLUMN "ai_business_document_config"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_document_config"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_document_config"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_document_config"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_document_config"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_business_document_config_uk_ai_business_document_object_code" ON "ai_business_document_config" ("tenant_id", "object_code");
CREATE UNIQUE INDEX "ai_business_document_config_uk_ai_business_document_object_id" ON "ai_business_document_config" ("tenant_id", "object_id");
CREATE INDEX "ai_business_document_config_idx_ai_business_document_suite" ON "ai_business_document_config" ("tenant_id", "suite_code");
CREATE INDEX "ai_business_document_config_idx_ai_business_document_config" ON "ai_business_document_config" ("tenant_id", "config_key");

