-- ai_business_flow_remote_command
CREATE TABLE IF NOT EXISTS "ai_business_flow_remote_command" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL,
  "command_key" char(64) NOT NULL,
  "command_type" varchar(32) NOT NULL,
  "request_digest" char(64) NOT NULL,
  "request_payload" text NOT NULL,
  "object_code" varchar(128) NOT NULL,
  "record_id" bigint NOT NULL,
  "business_key" varchar(160) NOT NULL,
  "flow_business_key" varchar(256) NOT NULL,
  "flow_model_key" varchar(128) NOT NULL,
  "process_instance_id" varchar(128) DEFAULT NULL,
  "command_status" varchar(32) NOT NULL DEFAULT 'PENDING',
  "retry_count" integer NOT NULL DEFAULT 0,
  "next_retry_time" timestamp DEFAULT NULL,
  "lock_owner" varchar(128) DEFAULT NULL,
  "lock_time" timestamp DEFAULT NULL,
  "error_type" varchar(128) DEFAULT NULL,
  "remote_succeeded_time" timestamp DEFAULT NULL,
  "completed_time" timestamp DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_flow_remote_command" IS '低代码流程远程命令恢复日志';
COMMENT ON COLUMN "ai_business_flow_remote_command"."id" IS '主键';
COMMENT ON COLUMN "ai_business_flow_remote_command"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_flow_remote_command"."command_key" IS '租户、命令类型与远端业务Key的稳定摘要';
COMMENT ON COLUMN "ai_business_flow_remote_command"."command_type" IS '命令类型，当前支持 START';
COMMENT ON COLUMN "ai_business_flow_remote_command"."request_digest" IS '规范请求载荷SHA-256摘要';
COMMENT ON COLUMN "ai_business_flow_remote_command"."request_payload" IS '恢复所需的不可变请求快照';
COMMENT ON COLUMN "ai_business_flow_remote_command"."object_code" IS '业务对象编码';
COMMENT ON COLUMN "ai_business_flow_remote_command"."record_id" IS '业务记录ID';
COMMENT ON COLUMN "ai_business_flow_remote_command"."business_key" IS '本地业务Key';
COMMENT ON COLUMN "ai_business_flow_remote_command"."flow_business_key" IS '提交给流程服务的幂等业务Key';
COMMENT ON COLUMN "ai_business_flow_remote_command"."flow_model_key" IS '流程模型Key';
COMMENT ON COLUMN "ai_business_flow_remote_command"."process_instance_id" IS '远端成功后返回或查回的流程实例ID';
COMMENT ON COLUMN "ai_business_flow_remote_command"."command_status" IS 'PENDING/PROCESSING/RETRY/REMOTE_SUCCEEDED/COMPLETED/DEAD';
COMMENT ON COLUMN "ai_business_flow_remote_command"."retry_count" IS '认领及恢复尝试次数';
COMMENT ON COLUMN "ai_business_flow_remote_command"."next_retry_time" IS '下次允许自动恢复时间';
COMMENT ON COLUMN "ai_business_flow_remote_command"."lock_owner" IS '恢复租约持有者';
COMMENT ON COLUMN "ai_business_flow_remote_command"."lock_time" IS '恢复租约时间';
COMMENT ON COLUMN "ai_business_flow_remote_command"."error_type" IS '最近失败类型，不保存异常消息和敏感数据';
COMMENT ON COLUMN "ai_business_flow_remote_command"."remote_succeeded_time" IS '确认远端成功时间';
COMMENT ON COLUMN "ai_business_flow_remote_command"."completed_time" IS '本地关联与状态提交完成时间';
