COMMENT ON COLUMN "ai_business_object"."description" IS '业务说明';
COMMENT ON COLUMN "ai_business_object"."status" IS '状态：1启用 0禁用';
COMMENT ON COLUMN "ai_business_object"."sort_order" IS '排序';
COMMENT ON COLUMN "ai_business_object"."options" IS '扩展配置';
COMMENT ON COLUMN "ai_business_object"."design_status" IS '设计状态：DRAFT草稿 DESIGNING设计中 READY待发布 PUBLISHED已发布 CHANGED有未发布变更';
