COMMENT ON COLUMN "ai_business_object"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_object"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_object"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_object"."update_time" IS '更新时间';
COMMENT ON COLUMN "ai_business_object"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
