--
-- Table structure for table `ai_business_object_design_version`
--
-- ai_business_object_design_version
CREATE TABLE IF NOT EXISTS "ai_business_object_design_version" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "object_id" bigint NOT NULL,
  "suite_code" varchar(48) NOT NULL,
  "object_code" varchar(48) NOT NULL,
  "config_id" bigint DEFAULT NULL,
  "config_key" varchar(128) DEFAULT NULL,
  "crud_config_version_id" bigint DEFAULT NULL,
  "version_no" integer NOT NULL,
  "version_type" varchar(32) NOT NULL DEFAULT 'draft',
  "model_snapshot" text DEFAULT NULL,
  "page_snapshot" text DEFAULT NULL,
  "relation_snapshot" text DEFAULT NULL,
  "designer_options_snapshot" text DEFAULT NULL,
  "publish_status" varchar(32) NOT NULL DEFAULT 'DRAFT',
  "publish_version" integer DEFAULT NULL,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_object_design_version" IS 'AI业务应用平台-业务对象设计版本表';
COMMENT ON COLUMN "ai_business_object_design_version"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_object_design_version"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_object_design_version"."object_id" IS '业务对象ID';
COMMENT ON COLUMN "ai_business_object_design_version"."suite_code" IS '业务套件编码';
COMMENT ON COLUMN "ai_business_object_design_version"."object_code" IS '业务对象编码';
COMMENT ON COLUMN "ai_business_object_design_version"."config_id" IS '关联低代码运行配置ID';
COMMENT ON COLUMN "ai_business_object_design_version"."config_key" IS '关联低代码运行配置键';
COMMENT ON COLUMN "ai_business_object_design_version"."crud_config_version_id" IS '关联AI CRUD发布版本ID';
COMMENT ON COLUMN "ai_business_object_design_version"."version_no" IS '对象设计版本号';
COMMENT ON COLUMN "ai_business_object_design_version"."version_type" IS '版本类型：draft/publish/rollback';
COMMENT ON COLUMN "ai_business_object_design_version"."model_snapshot" IS '模型Schema快照';
COMMENT ON COLUMN "ai_business_object_design_version"."page_snapshot" IS '页面Schema快照';
COMMENT ON COLUMN "ai_business_object_design_version"."relation_snapshot" IS '关系配置快照';
COMMENT ON COLUMN "ai_business_object_design_version"."designer_options_snapshot" IS '表单优先设计器扩展快照';
COMMENT ON COLUMN "ai_business_object_design_version"."publish_status" IS '发布状态：DRAFT/PUBLISHED/FAILED';
COMMENT ON COLUMN "ai_business_object_design_version"."publish_version" IS '发布版本号';
COMMENT ON COLUMN "ai_business_object_design_version"."remark" IS '备注';
COMMENT ON COLUMN "ai_business_object_design_version"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_object_design_version"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_object_design_version"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_object_design_version"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_object_design_version"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_business_object_design_version_uk_ai_business_desig_4a11d7f6" ON "ai_business_object_design_version" ("tenant_id", "object_id", "version_no");
CREATE INDEX "ai_business_object_design_version_idx_ai_business_desi_c350b992" ON "ai_business_object_design_version" ("tenant_id", "object_id", "version_no");
CREATE INDEX "ai_business_object_design_version_idx_ai_business_desi_e3fa20e0" ON "ai_business_object_design_version" ("tenant_id", "crud_config_version_id");

