--
-- Table structure for table `ai_business_object_relation`
--
-- ai_business_object_relation
CREATE TABLE IF NOT EXISTS "ai_business_object_relation" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "suite_code" varchar(48) NOT NULL,
  "source_object_code" varchar(48) NOT NULL,
  "target_object_code" varchar(48) NOT NULL,
  "relation_type" varchar(32) NOT NULL,
  "relation_name" varchar(128) NOT NULL,
  "source_field_code" varchar(64) DEFAULT NULL,
  "target_field_code" varchar(64) DEFAULT NULL,
  "relation_config" text DEFAULT NULL,
  "description" varchar(500) DEFAULT NULL,
  "status" integer NOT NULL DEFAULT 1,
  "sort_order" integer NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_object_relation" IS 'AI业务应用平台-业务对象关系表';
COMMENT ON COLUMN "ai_business_object_relation"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_object_relation"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_object_relation"."suite_code" IS '所属业务套件编码';
COMMENT ON COLUMN "ai_business_object_relation"."source_object_code" IS '来源业务对象编码';
COMMENT ON COLUMN "ai_business_object_relation"."target_object_code" IS '目标业务对象编码';
COMMENT ON COLUMN "ai_business_object_relation"."relation_type" IS '关系类型：REFERENCE/DETAIL/CHILD_LIST/MANY_TO_MANY';
COMMENT ON COLUMN "ai_business_object_relation"."relation_name" IS '关系名称';
COMMENT ON COLUMN "ai_business_object_relation"."source_field_code" IS '来源对象字段编码';
COMMENT ON COLUMN "ai_business_object_relation"."target_field_code" IS '目标对象字段编码';
COMMENT ON COLUMN "ai_business_object_relation"."relation_config" IS '关系配置';
COMMENT ON COLUMN "ai_business_object_relation"."description" IS '关系说明';
COMMENT ON COLUMN "ai_business_object_relation"."status" IS '状态：1启用 0禁用';
COMMENT ON COLUMN "ai_business_object_relation"."sort_order" IS '排序';
COMMENT ON COLUMN "ai_business_object_relation"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_object_relation"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_object_relation"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_object_relation"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_object_relation"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_business_object_relation_uk_ai_business_relation_scope" ON "ai_business_object_relation" ("tenant_id", "suite_code", "source_object_code", "target_object_code", "relation_type", "relation_name");
CREATE INDEX "ai_business_object_relation_idx_ai_business_relation_source" ON "ai_business_object_relation" ("tenant_id", "suite_code", "source_object_code", "status");
CREATE INDEX "ai_business_object_relation_idx_ai_business_relation_target" ON "ai_business_object_relation" ("tenant_id", "suite_code", "target_object_code", "status");

