-- ai_business_process
CREATE TABLE IF NOT EXISTS "ai_business_process" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "application_id" bigint NOT NULL,
  "process_code" varchar(128) NOT NULL,
  "process_name" varchar(128) NOT NULL,
  "process_description" varchar(500) DEFAULT NULL,
  "subject_object_id" bigint NOT NULL,
  "subject_object_code" varchar(128) NOT NULL,
  "draft_schema_json" text NOT NULL,
  "draft_schema_hash" char(64) NOT NULL,
  "design_status" varchar(32) NOT NULL DEFAULT 'DRAFT',
  "current_version" integer NOT NULL DEFAULT 0,
  "published_version" integer DEFAULT NULL,
  "status" smallint NOT NULL DEFAULT 1,
  "legacy_source_type" varchar(32) DEFAULT NULL,
  "legacy_source_id" varchar(128) DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_business_process" IS '应用级业务流程定义与设计草稿';
COMMENT ON COLUMN "ai_business_process"."id" IS '主键ID';
COMMENT ON COLUMN "ai_business_process"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_business_process"."application_id" IS '所属业务应用ID';
COMMENT ON COLUMN "ai_business_process"."process_code" IS '应用内稳定流程编码，创建后不可修改';
COMMENT ON COLUMN "ai_business_process"."process_name" IS '业务流程名称';
COMMENT ON COLUMN "ai_business_process"."process_description" IS '业务流程说明';
COMMENT ON COLUMN "ai_business_process"."subject_object_id" IS '主业务对象ID';
COMMENT ON COLUMN "ai_business_process"."subject_object_code" IS '主业务对象编码';
COMMENT ON COLUMN "ai_business_process"."draft_schema_json" IS 'businessProcessJson草稿，不保存敏感配置';
COMMENT ON COLUMN "ai_business_process"."draft_schema_hash" IS '规范化草稿SHA-256摘要';
COMMENT ON COLUMN "ai_business_process"."design_status" IS 'DRAFT/VALIDATED/PUBLISHED/CHANGED';
COMMENT ON COLUMN "ai_business_process"."current_version" IS '当前已生成流程版本号';
COMMENT ON COLUMN "ai_business_process"."published_version" IS '当前应用快照引用的流程版本号';
COMMENT ON COLUMN "ai_business_process"."status" IS '状态：1启用 0停用';
COMMENT ON COLUMN "ai_business_process"."legacy_source_type" IS '旧来源类型：TRIGGER/FLOW_BINDING/AUTOMATION_ACTION';
COMMENT ON COLUMN "ai_business_process"."legacy_source_id" IS '旧来源稳定ID';
COMMENT ON COLUMN "ai_business_process"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
COMMENT ON COLUMN "ai_business_process"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_business_process"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_business_process"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_business_process"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_business_process"."update_time" IS '更新时间';
