--
-- ai_code_rule
CREATE TABLE IF NOT EXISTS "ai_code_rule" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "rule_code" varchar(64) NOT NULL,
  "rule_name" varchar(128) NOT NULL,
  "scene" varchar(64) NOT NULL DEFAULT 'COMMON',
  "category" varchar(64) NOT NULL DEFAULT 'COMMON',
  "source_object_id" bigint DEFAULT NULL,
  "source_object_code" varchar(64) DEFAULT NULL,
  "template" varchar(256) NOT NULL,
  "reset_policy" varchar(32) NOT NULL DEFAULT 'AUTO',
  "seq_length" integer NOT NULL DEFAULT 4,
  "status" smallint NOT NULL DEFAULT 1,
  "builtin" smallint NOT NULL DEFAULT 0,
  "in_code_list" smallint NOT NULL DEFAULT 1,
  "version_no" integer NOT NULL DEFAULT 1,
  "legacy_compat_enabled" smallint NOT NULL DEFAULT 1,
  "remark" varchar(500) DEFAULT NULL,
  "options" text DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_code_rule" IS 'AI业务应用平台-通用编码规则';
COMMENT ON COLUMN "ai_code_rule"."id" IS '主键ID';
COMMENT ON COLUMN "ai_code_rule"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_code_rule"."rule_code" IS '规则编码';
COMMENT ON COLUMN "ai_code_rule"."rule_name" IS '规则名称';
COMMENT ON COLUMN "ai_code_rule"."scene" IS '适用场景：COMMON通用/DOCUMENT单据/MATERIAL物料等';
COMMENT ON COLUMN "ai_code_rule"."category" IS '编码分类';
COMMENT ON COLUMN "ai_code_rule"."source_object_id" IS '业务字段来源对象ID';
COMMENT ON COLUMN "ai_code_rule"."source_object_code" IS '业务字段来源对象编码';
COMMENT ON COLUMN "ai_code_rule"."template" IS '编码模板';
COMMENT ON COLUMN "ai_code_rule"."reset_policy" IS '流水重置策略：AUTO/NONE/YEAR/MONTH/DAY/HOUR/MINUTE/SECOND';
COMMENT ON COLUMN "ai_code_rule"."seq_length" IS '默认流水号长度';
COMMENT ON COLUMN "ai_code_rule"."status" IS '状态：1启用 0停用';
COMMENT ON COLUMN "ai_code_rule"."builtin" IS '是否内置规则';
COMMENT ON COLUMN "ai_code_rule"."in_code_list" IS '是否可在业务配置中选择';
COMMENT ON COLUMN "ai_code_rule"."version_no" IS '乐观锁版本号';
COMMENT ON COLUMN "ai_code_rule"."legacy_compat_enabled" IS '是否兼容旧编码计数器水位';
COMMENT ON COLUMN "ai_code_rule"."remark" IS '备注';
COMMENT ON COLUMN "ai_code_rule"."options" IS '扩展配置JSON';
COMMENT ON COLUMN "ai_code_rule"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_code_rule"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_code_rule"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_code_rule"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_code_rule"."update_time" IS '更新时间';
COMMENT ON COLUMN "ai_code_rule"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "ai_code_rule_uk_ai_code_rule_code_active" ON "ai_code_rule" ("tenant_id", "rule_code", "del_flag");
CREATE INDEX "ai_code_rule_idx_ai_code_rule_scene" ON "ai_code_rule" ("tenant_id", "scene", "status");
CREATE INDEX "ai_code_rule_idx_ai_code_rule_update" ON "ai_code_rule" ("tenant_id", "update_time");
CREATE INDEX "ai_code_rule_idx_ai_code_rule_category" ON "ai_code_rule" ("tenant_id", "category", "status", "del_flag");
CREATE INDEX "ai_code_rule_idx_ai_code_rule_source_object" ON "ai_code_rule" ("tenant_id", "source_object_code", "status", "del_flag");

