  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_code_rule_segment" IS '编码规则结构化分段';
COMMENT ON COLUMN "ai_code_rule_segment"."id" IS '分段ID';
