-- ai_context_config
CREATE TABLE IF NOT EXISTS "ai_context_config" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint DEFAULT 1,
  "agent_code" varchar(64) NOT NULL,
  "config_name" varchar(128) NOT NULL,
  "config_content" text NOT NULL,
  "config_type" varchar(32) NOT NULL DEFAULT 'SPEC',
  "sort" integer DEFAULT 0,
  "status" char(1) DEFAULT '0',
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "del_flag" char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_context_config" IS 'AI上下文配置表';
COMMENT ON COLUMN "ai_context_config"."id" IS '主键';
COMMENT ON COLUMN "ai_context_config"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_context_config"."agent_code" IS '关联Agent编码';
COMMENT ON COLUMN "ai_context_config"."config_name" IS '配置名称';
COMMENT ON COLUMN "ai_context_config"."config_content" IS '上下文内容';
COMMENT ON COLUMN "ai_context_config"."config_type" IS '类型：SPEC/SAMPLE/RULE';
