COMMENT ON COLUMN "ai_context_config"."status" IS '状态（0正常 1停用）';
COMMENT ON COLUMN "ai_context_config"."create_by" IS '创建者';
COMMENT ON COLUMN "ai_context_config"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_context_config"."create_dept" IS '创建部门ID';
COMMENT ON COLUMN "ai_context_config"."update_by" IS '更新者';
COMMENT ON COLUMN "ai_context_config"."update_time" IS '更新时间';
COMMENT ON COLUMN "ai_context_config"."del_flag" IS '删除标志（0正常 1删除）';
CREATE INDEX "ai_context_config_idx_agent_code" ON "ai_context_config" ("agent_code");

