COMMENT ON COLUMN "ai_crud_config"."menu_name" IS '菜单名称';
COMMENT ON COLUMN "ai_crud_config"."menu_parent_id" IS '菜单父级ID';
COMMENT ON COLUMN "ai_crud_config"."menu_sort" IS '菜单排序';
COMMENT ON COLUMN "ai_crud_config"."menu_resource_id" IS '关联的sys_resource记录ID';
COMMENT ON COLUMN "ai_crud_config"."dict_config" IS '字典数据配置';
COMMENT ON COLUMN "ai_crud_config"."desensitize_config" IS '字段脱敏配置';
COMMENT ON COLUMN "ai_crud_config"."encrypt_config" IS '接口加解密配置';
COMMENT ON COLUMN "ai_crud_config"."trans_config" IS '字典翻译配置';
COMMENT ON COLUMN "ai_crud_config"."layout_type" IS '页面模板类型（对应 ai_page_template.template_key）';
COMMENT ON COLUMN "ai_crud_config"."model_schema" IS '可视化数据模型协议';
COMMENT ON COLUMN "ai_crud_config"."page_schema" IS '可视化页面搭建协议';
COMMENT ON COLUMN "ai_crud_config"."draft_version" IS '草稿版本号';
COMMENT ON COLUMN "ai_crud_config"."published_version" IS '已发布版本号';
COMMENT ON COLUMN "ai_crud_config"."publish_time" IS '发布时间';
COMMENT ON COLUMN "ai_crud_config"."publish_by" IS '发布人';
COMMENT ON COLUMN "ai_crud_config"."domain_id" IS '业务领域ID';
COMMENT ON COLUMN "ai_crud_config"."domain_code" IS '业务领域编码';
COMMENT ON COLUMN "ai_crud_config"."object_code" IS '业务对象编码';
COMMENT ON COLUMN "ai_crud_config"."object_name" IS '业务对象名称';
COMMENT ON COLUMN "ai_crud_config"."create_by" IS '创建者';
COMMENT ON COLUMN "ai_crud_config"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_crud_config"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_crud_config"."update_by" IS '更新者';
COMMENT ON COLUMN "ai_crud_config"."update_time" IS '更新时间';
COMMENT ON COLUMN "ai_crud_config"."runtime_datasource_id" IS '运行数据源ID';
COMMENT ON COLUMN "ai_crud_config"."runtime_datasource_code" IS '运行数据源编码';
COMMENT ON COLUMN "ai_crud_config"."runtime_datasource_snapshot" IS '运行数据源快照，不含密码';
COMMENT ON COLUMN "ai_crud_config"."runtime_table_name" IS '运行表名';
COMMENT ON COLUMN "ai_crud_config"."primary_key_field" IS '主键字段名';
COMMENT ON COLUMN "ai_crud_config"."primary_key_column" IS '主键列名';
COMMENT ON COLUMN "ai_crud_config"."primary_key_type" IS '主键类型';
COMMENT ON COLUMN "ai_crud_config"."tenant_strategy" IS '租户隔离策略';
COMMENT ON COLUMN "ai_crud_config"."audit_strategy" IS '审计字段策略';
