--
-- Table structure for table `ai_formula_function`
--
-- ai_formula_function
CREATE TABLE IF NOT EXISTS "ai_formula_function" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "function_code" varchar(64) NOT NULL,
  "display_name" varchar(128) NOT NULL,
  "category" varchar(64) NOT NULL,
  "description" varchar(500) DEFAULT NULL,
  "source_type" varchar(32) NOT NULL DEFAULT 'BUILTIN',
  "argument_schema" text DEFAULT NULL,
  "return_type" varchar(32) DEFAULT NULL,
  "example" text,
  "status" varchar(32) NOT NULL DEFAULT 'ENABLED',
  "current_version" varchar(32) DEFAULT NULL,
  "latest_version" varchar(32) DEFAULT NULL,
  "builtin" smallint NOT NULL DEFAULT 0,
  "sort_order" integer NOT NULL DEFAULT 0,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_formula_function" IS 'AI业务应用平台-公式函数注册表';
COMMENT ON COLUMN "ai_formula_function"."id" IS '主键ID';
COMMENT ON COLUMN "ai_formula_function"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_formula_function"."function_code" IS '函数编码';
COMMENT ON COLUMN "ai_formula_function"."display_name" IS '展示名称';
COMMENT ON COLUMN "ai_formula_function"."category" IS '函数分类';
COMMENT ON COLUMN "ai_formula_function"."description" IS '函数说明';
COMMENT ON COLUMN "ai_formula_function"."source_type" IS '来源类型：BUILTIN/SYSTEM/TENANT/MARKET';
COMMENT ON COLUMN "ai_formula_function"."argument_schema" IS '参数Schema';
COMMENT ON COLUMN "ai_formula_function"."return_type" IS '返回类型';
COMMENT ON COLUMN "ai_formula_function"."example" IS '示例';
COMMENT ON COLUMN "ai_formula_function"."status" IS '状态：ENABLED/DISABLED';
COMMENT ON COLUMN "ai_formula_function"."current_version" IS '当前版本';
COMMENT ON COLUMN "ai_formula_function"."latest_version" IS '最新版本';
COMMENT ON COLUMN "ai_formula_function"."builtin" IS '是否内置函数';
COMMENT ON COLUMN "ai_formula_function"."sort_order" IS '排序号';
COMMENT ON COLUMN "ai_formula_function"."remark" IS '备注';
COMMENT ON COLUMN "ai_formula_function"."create_by" IS '创建人';
COMMENT ON COLUMN "ai_formula_function"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_formula_function"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_formula_function"."update_by" IS '更新人';
COMMENT ON COLUMN "ai_formula_function"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_formula_function_uk_ai_formula_function_code" ON "ai_formula_function" ("tenant_id", "function_code");
CREATE INDEX "ai_formula_function_idx_ai_formula_function_query" ON "ai_formula_function" ("tenant_id", "category", "source_type", "status");

