-- ai_page_template
CREATE TABLE IF NOT EXISTS "ai_page_template" (
  "id" bigint NOT NULL,
  "template_key" varchar(64) NOT NULL,
  "template_name" varchar(128) NOT NULL,
  "description" varchar(512) DEFAULT '',
  "icon" varchar(64) DEFAULT '',
  "system_prompt" text,
  "schema_hint" text DEFAULT NULL,
  "default_config" text DEFAULT NULL,
  "enabled" smallint NOT NULL DEFAULT 1,
  "sort" integer NOT NULL DEFAULT 0,
  "is_builtin" smallint NOT NULL DEFAULT 0,
  "codegen_type" varchar(16) NOT NULL DEFAULT 'TEMPLATE',
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_page_template" IS 'AI页面模板表（组件市场）';
COMMENT ON COLUMN "ai_page_template"."id" IS '主键';
COMMENT ON COLUMN "ai_page_template"."template_key" IS '模板唯一标识（如 simple-crud / tree-crud）';
COMMENT ON COLUMN "ai_page_template"."template_name" IS '模板显示名称';
COMMENT ON COLUMN "ai_page_template"."description" IS '模板描述';
COMMENT ON COLUMN "ai_page_template"."icon" IS '图标（mdi: 前缀）';
COMMENT ON COLUMN "ai_page_template"."system_prompt" IS '该模板专属的 AI system prompt 补充';
COMMENT ON COLUMN "ai_page_template"."schema_hint" IS '告诉 AI 该模板可用的字段约束（JSON）';
COMMENT ON COLUMN "ai_page_template"."default_config" IS '默认配置值（JSON，如 modalType/searchGridCols 等）';
COMMENT ON COLUMN "ai_page_template"."enabled" IS '是否启用（1启用 0停用）';
COMMENT ON COLUMN "ai_page_template"."sort" IS '排序';
COMMENT ON COLUMN "ai_page_template"."is_builtin" IS '是否内置（1内置不可删除）';
COMMENT ON COLUMN "ai_page_template"."codegen_type" IS '代码生成策略：TEMPLATE-Velocity模板 / AI-大模型生成';
COMMENT ON COLUMN "ai_page_template"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "ai_page_template_uk_template_key_active" ON "ai_page_template" ("template_key", "del_flag");

--
-- Dumping data for table `ai_page_template`
--
INSERT INTO "ai_page_template" VALUES (1,'simple-crud','标准 CRUD','适合平坦型数据的属性增删改查，支持搜索、表格列表、弹窗/抒屉表单编辑','mdi:table','当前模板为「标准 CRUD」，请确保：\n1. columnsSchema 包含内容列 + 操作列(actions)\n2. editSchema 简洁清晰，不要嵌套\n3. modalType 默认为 drawer\n4. 尽量岑减搜索条件，保留最常用的3-5个',NULL,'{"modalType": "drawer", "modalWidth": "800px", "editGridCols": 1, "searchGridCols": 4}',1,1,1,'TEMPLATE',NULL,'2026-04-26 17:05:23',NULL,1,'2026-04-26 17:20:22',0),(2,'tree-crud','树形 CRUD','适合具有父子层级结构的数据，如部门结构、分类管理等，左树右表格布局','mdi:file-tree','当前模板为「树形 CRUD」，请确保：\n1. editSchema 中必须包含 parentId 字段（type: treeSelect）\n2. editSchema 中包含 sort 排序字段\n3. columnsSchema 中包含 层级深度或父层名称列\n4. apiConfig 中包含 tree 接口（查询树形结构）\n5. treeConfig 配置：{"keyField": "id", "parentField": "parentId", "labelField": "name"}\n6. 数据必须有 parent_id 字段，不要导入进 editSchema\n7. 模式必须为 modal','{"treeConfig": {"keyField": "id", "labelField": "name", "parentField": "parentId"}}','{"modalType": "modal", "modalWidth": "600px", "editGridCols": 1, "searchGridCols": 3}',1,2,1,'TEMPLATE',NULL,'2026-04-26 17:05:23',NULL,1,'2026-04-30 15:53:18',0);

