SELECT CASE
  WHEN (SELECT MAX("id") FROM "ai_report_project") IS NULL
    THEN setval(pg_get_serial_sequence('ai_report_project', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('ai_report_project', 'id'),
              (SELECT MAX("id") FROM "ai_report_project"), true)
END;

--
-- Table structure for table `ai_report_project_version`
--
-- ai_report_project_version
CREATE TABLE IF NOT EXISTS "ai_report_project_version" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "project_id" bigint NOT NULL,
  "project_name" varchar(100) NOT NULL,
  "version_no" integer NOT NULL,
  "version_name" varchar(32) NOT NULL,
  "operation_type" varchar(20) NOT NULL DEFAULT 'publish',
  "source_version_id" bigint DEFAULT NULL,
  "publisher_id" bigint DEFAULT NULL,
  "publisher_name" varchar(100) DEFAULT NULL,
  "publish_time" timestamp DEFAULT NULL,
  "publish_url" varchar(500) DEFAULT NULL,
  "index_img" varchar(500) DEFAULT NULL,
  "canvas_width" integer DEFAULT NULL,
  "canvas_height" integer DEFAULT NULL,
  "background_color" varchar(20) DEFAULT NULL,
  "component_data" text,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_report_project_version" IS '大屏项目发布版本表';
COMMENT ON COLUMN "ai_report_project_version"."id" IS '主键ID';
COMMENT ON COLUMN "ai_report_project_version"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_report_project_version"."project_id" IS '大屏项目ID';
COMMENT ON COLUMN "ai_report_project_version"."project_name" IS '大屏项目名称';
COMMENT ON COLUMN "ai_report_project_version"."version_no" IS '版本号';
COMMENT ON COLUMN "ai_report_project_version"."version_name" IS '版本名称';
COMMENT ON COLUMN "ai_report_project_version"."operation_type" IS '操作类型：publish发布 rollback回退';
COMMENT ON COLUMN "ai_report_project_version"."source_version_id" IS '回退来源版本ID';
COMMENT ON COLUMN "ai_report_project_version"."publisher_id" IS '发布人ID';
COMMENT ON COLUMN "ai_report_project_version"."publisher_name" IS '发布人名称';
COMMENT ON COLUMN "ai_report_project_version"."publish_time" IS '发布时间';
COMMENT ON COLUMN "ai_report_project_version"."publish_url" IS '发布地址';
COMMENT ON COLUMN "ai_report_project_version"."index_img" IS '封面图文件ID';
COMMENT ON COLUMN "ai_report_project_version"."canvas_width" IS '画布宽度';
COMMENT ON COLUMN "ai_report_project_version"."canvas_height" IS '画布高度';
COMMENT ON COLUMN "ai_report_project_version"."background_color" IS '背景颜色';
COMMENT ON COLUMN "ai_report_project_version"."component_data" IS '组件配置JSON';
COMMENT ON COLUMN "ai_report_project_version"."remark" IS '备注';
COMMENT ON COLUMN "ai_report_project_version"."create_by" IS '创建者';
COMMENT ON COLUMN "ai_report_project_version"."create_time" IS '创建时间';
COMMENT ON COLUMN "ai_report_project_version"."create_dept" IS '创建部门';
COMMENT ON COLUMN "ai_report_project_version"."update_by" IS '更新者';
COMMENT ON COLUMN "ai_report_project_version"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "ai_report_project_version_uk_report_project_version_no" ON "ai_report_project_version" ("tenant_id", "project_id", "version_no");
CREATE INDEX "ai_report_project_version_idx_report_project_version_project" ON "ai_report_project_version" ("tenant_id", "project_id", "create_time");
CREATE INDEX "ai_report_project_version_idx_report_project_version_publisher" ON "ai_report_project_version" ("tenant_id", "publisher_id", "publish_time");

