--
-- Table structure for table `ai_report_template`
--
-- ai_report_template
CREATE TABLE IF NOT EXISTS "ai_report_template" (
  "id" bigint NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "source_project_id" bigint NOT NULL,
  "directory_id" bigint DEFAULT NULL,
  "template_name" varchar(100) NOT NULL,
  "remark" varchar(500) DEFAULT NULL,
  "index_img" varchar(500) DEFAULT NULL,
  "status" char(1) NOT NULL DEFAULT '0',
  "canvas_width" integer NOT NULL DEFAULT 1920,
  "canvas_height" integer NOT NULL DEFAULT 1080,
  "background_color" varchar(20) DEFAULT '#1e1e2e',
  "component_data" text,
  "publish_status" char(1) NOT NULL DEFAULT '0',
  "template_scope" char(1) NOT NULL DEFAULT '0',
  "publish_url" varchar(500) DEFAULT NULL,
  "publish_time" timestamp DEFAULT NULL,
  "copied_count" integer NOT NULL DEFAULT 0,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "ai_report_template" IS '模板表';
COMMENT ON COLUMN "ai_report_template"."id" IS '模板ID';
COMMENT ON COLUMN "ai_report_template"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "ai_report_template"."source_project_id" IS '来源项目ID';
COMMENT ON COLUMN "ai_report_template"."directory_id" IS '所属目录ID';
COMMENT ON COLUMN "ai_report_template"."template_name" IS '模板名称';
COMMENT ON COLUMN "ai_report_template"."remark" IS '备注';
COMMENT ON COLUMN "ai_report_template"."index_img" IS '封面图URL';
COMMENT ON COLUMN "ai_report_template"."status" IS '状态（0正常 1停用）';
COMMENT ON COLUMN "ai_report_template"."canvas_width" IS '画布宽度';
COMMENT ON COLUMN "ai_report_template"."canvas_height" IS '画布高度';
