--
-- Table structure for table `gen_datasource`
--
-- gen_datasource
CREATE TABLE IF NOT EXISTS "gen_datasource" (
  "datasource_id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "datasource_name" varchar(100) NOT NULL,
  "datasource_code" varchar(50) NOT NULL,
  "db_type" varchar(20) NOT NULL DEFAULT 'MySQL',
  "driver_class_name" varchar(200) NOT NULL,
  "url" varchar(500) NOT NULL,
  "username" varchar(100) NOT NULL,
  "password" varchar(200) NOT NULL,
  "is_default" smallint DEFAULT 0,
  "is_enabled" smallint DEFAULT 1,
  "test_query" varchar(200) DEFAULT 'SELECT 1',
  "sort" integer DEFAULT 0,
  "remark" varchar(500) DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_by" varchar(64) DEFAULT NULL,
  "update_by" varchar(64) DEFAULT NULL,
  "usage_scope" varchar(32) NOT NULL DEFAULT 'BOTH',
  "allow_runtime_write" smallint NOT NULL DEFAULT 1,
  "allow_runtime_ddl" smallint NOT NULL DEFAULT 0,
  "readonly" smallint NOT NULL DEFAULT 0,
  "risk_level" varchar(16) NOT NULL DEFAULT 'MEDIUM',
  PRIMARY KEY ("datasource_id")
);
COMMENT ON TABLE "gen_datasource" IS '代码生成器数据源配置';
COMMENT ON COLUMN "gen_datasource"."datasource_id" IS '数据源ID';
COMMENT ON COLUMN "gen_datasource"."datasource_name" IS '数据源名称';
COMMENT ON COLUMN "gen_datasource"."datasource_code" IS '数据源编码（唯一标识）';
COMMENT ON COLUMN "gen_datasource"."db_type" IS '数据库类型：MySQL/Oracle/PostgreSQL/SQLServer';
COMMENT ON COLUMN "gen_datasource"."driver_class_name" IS '驱动类名';
COMMENT ON COLUMN "gen_datasource"."url" IS 'JDBC连接地址';
COMMENT ON COLUMN "gen_datasource"."username" IS '用户名';
COMMENT ON COLUMN "gen_datasource"."password" IS '密码（加密存储）';
COMMENT ON COLUMN "gen_datasource"."is_default" IS '是否默认数据源（1-是，0-否）';
COMMENT ON COLUMN "gen_datasource"."is_enabled" IS '是否启用（1-启用，0-禁用）';
COMMENT ON COLUMN "gen_datasource"."test_query" IS '测试查询SQL';
COMMENT ON COLUMN "gen_datasource"."sort" IS '排序';
COMMENT ON COLUMN "gen_datasource"."remark" IS '备注';
COMMENT ON COLUMN "gen_datasource"."create_time" IS '创建时间';
COMMENT ON COLUMN "gen_datasource"."update_time" IS '更新时间';
COMMENT ON COLUMN "gen_datasource"."create_by" IS '创建者';
COMMENT ON COLUMN "gen_datasource"."update_by" IS '更新者';
COMMENT ON COLUMN "gen_datasource"."usage_scope" IS '数据源用途范围：LOWCODE_RUNTIME/TENANT_BUSINESS/DEVELOPER_IMPORT/BOTH';
COMMENT ON COLUMN "gen_datasource"."allow_runtime_write" IS '是否允许低代码运行时写入';
COMMENT ON COLUMN "gen_datasource"."allow_runtime_ddl" IS '是否允许低代码执行运行时DDL';
COMMENT ON COLUMN "gen_datasource"."readonly" IS '是否只读';
COMMENT ON COLUMN "gen_datasource"."risk_level" IS '风险等级：LOW/MEDIUM/HIGH';
CREATE UNIQUE INDEX "gen_datasource_uk_datasource_code" ON "gen_datasource" ("datasource_code");
CREATE INDEX "gen_datasource_idx_is_default" ON "gen_datasource" ("is_default");
CREATE INDEX "gen_datasource_idx_is_enabled" ON "gen_datasource" ("is_enabled");

