COMMENT ON COLUMN "sys_api_config"."limit_flag" IS '是否开启限流';
COMMENT ON COLUMN "sys_api_config"."sensitive_fields" IS '需脱敏字段 (JSON数组存储, 如 ["phone", "id_card"])';
COMMENT ON COLUMN "sys_api_config"."status" IS '状态 (1-正常, 0-停用)';
COMMENT ON COLUMN "sys_api_config"."remark" IS '备注说明';
COMMENT ON COLUMN "sys_api_config"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_api_config"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_api_config"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_api_config"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_api_config"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_api_config"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
