--
-- Table structure for table `sys_dict_data`
--
-- sys_dict_data
CREATE TABLE IF NOT EXISTS "sys_dict_data" (
  "dict_code" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint DEFAULT 0,
  "dict_sort" integer DEFAULT 0,
  "dict_label" varchar(100) DEFAULT '',
  "dict_value" varchar(100) DEFAULT '',
  "dict_type" varchar(100) DEFAULT '',
  "css_class" varchar(100) DEFAULT NULL,
  "list_class" varchar(100) DEFAULT NULL,
  "is_default" char(1) DEFAULT 'N',
  "parent_dict_code" bigint DEFAULT NULL,
  "linked_dict_type" varchar(100) DEFAULT NULL,
  "linked_dict_value" varchar(100) DEFAULT NULL,
  "dict_status" smallint DEFAULT 1,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("dict_code")
);
COMMENT ON TABLE "sys_dict_data" IS '字典数据表';
COMMENT ON COLUMN "sys_dict_data"."dict_code" IS '字典编码';
COMMENT ON COLUMN "sys_dict_data"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_dict_data"."dict_sort" IS '字典排序';
COMMENT ON COLUMN "sys_dict_data"."dict_label" IS '字典标签';
COMMENT ON COLUMN "sys_dict_data"."dict_value" IS '字典键值';
COMMENT ON COLUMN "sys_dict_data"."dict_type" IS '字典类型';
COMMENT ON COLUMN "sys_dict_data"."css_class" IS '样式属性（其他样式扩展）';
COMMENT ON COLUMN "sys_dict_data"."list_class" IS '表格回显样式';
COMMENT ON COLUMN "sys_dict_data"."is_default" IS '是否默认（Y是 N否）';
COMMENT ON COLUMN "sys_dict_data"."parent_dict_code" IS '上级字典编码';
COMMENT ON COLUMN "sys_dict_data"."linked_dict_type" IS '关联的字典类型';
COMMENT ON COLUMN "sys_dict_data"."linked_dict_value" IS '关联的字典值';
COMMENT ON COLUMN "sys_dict_data"."dict_status" IS '字典状态（0-禁用，1-正常）';
COMMENT ON COLUMN "sys_dict_data"."remark" IS '备注';
COMMENT ON COLUMN "sys_dict_data"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_dict_data"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_dict_data"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_dict_data"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_dict_data"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_dict_data"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "sys_dict_data_uk_tenant_dict_data_active" ON "sys_dict_data" ("tenant_id", "dict_type", "dict_value", "del_flag");
CREATE INDEX "sys_dict_data_idx_tenant_dict_type" ON "sys_dict_data" ("tenant_id", "dict_type");
CREATE INDEX "sys_dict_data_idx_parent_dict_code" ON "sys_dict_data" ("parent_dict_code");
CREATE INDEX "sys_dict_data_idx_linked_dict" ON "sys_dict_data" ("linked_dict_type", "linked_dict_value");

