--
-- Table structure for table `sys_dict_type`
--
-- sys_dict_type
CREATE TABLE IF NOT EXISTS "sys_dict_type" (
  "dict_id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint DEFAULT 0,
  "dict_name" varchar(100) DEFAULT '',
  "dict_type" varchar(100) DEFAULT '',
  "dict_status" smallint DEFAULT 1,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("dict_id")
);
COMMENT ON TABLE "sys_dict_type" IS '字典类型表';
COMMENT ON COLUMN "sys_dict_type"."dict_id" IS '字典主键';
COMMENT ON COLUMN "sys_dict_type"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_dict_type"."dict_name" IS '字典名称';
COMMENT ON COLUMN "sys_dict_type"."dict_type" IS '字典类型（租户内唯一）';
COMMENT ON COLUMN "sys_dict_type"."dict_status" IS '字典状态（0-禁用，1-正常）';
COMMENT ON COLUMN "sys_dict_type"."remark" IS '备注';
COMMENT ON COLUMN "sys_dict_type"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_dict_type"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_dict_type"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_dict_type"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_dict_type"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_dict_type"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "sys_dict_type_uk_tenant_dict_type_active" ON "sys_dict_type" ("tenant_id", "dict_type", "del_flag");
CREATE INDEX "sys_dict_type_idx_dict_status" ON "sys_dict_type" ("dict_status");

--
-- Dumping data for table `sys_dict_type`
--
SELECT CASE
  WHEN (SELECT MAX("dict_id") FROM "sys_dict_type") IS NULL
    THEN setval(pg_get_serial_sequence('sys_dict_type', 'dict_id'), 1, false)
  ELSE setval(pg_get_serial_sequence('sys_dict_type', 'dict_id'),
