--
-- Table structure for table `sys_email_config`
--
-- sys_email_config
CREATE TABLE IF NOT EXISTS "sys_email_config" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "config_id" varchar(64) DEFAULT NULL,
  "smtp_server" varchar(128) NOT NULL,
  "port" integer DEFAULT 465,
  "username" varchar(128) DEFAULT NULL,
  "password" varchar(256) DEFAULT NULL,
  "from_address" varchar(128) NOT NULL,
  "from_name" varchar(64) DEFAULT NULL,
  "is_ssl" smallint DEFAULT 1,
  "is_auth" smallint DEFAULT 1,
  "retry_interval" integer DEFAULT 5,
  "max_retries" integer DEFAULT 1,
  "status" smallint DEFAULT 0,
  "tenant_id" bigint DEFAULT NULL,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "create_by" varchar(64) DEFAULT NULL,
  "update_by" varchar(64) DEFAULT NULL,
  "remark" varchar(500) DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_email_config" IS '邮件配置表';
COMMENT ON COLUMN "sys_email_config"."id" IS '主键';
COMMENT ON COLUMN "sys_email_config"."config_id" IS '配置标识';
