--
-- Table structure for table `sys_file_storage_config`
--
-- sys_file_storage_config
CREATE TABLE IF NOT EXISTS "sys_file_storage_config" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "config_name" varchar(100) NOT NULL,
  "storage_type" varchar(50) NOT NULL,
  "is_default" smallint DEFAULT 0,
  "enabled" smallint DEFAULT 1,
  "endpoint" varchar(500) DEFAULT NULL,
  "access_key" varchar(200) DEFAULT NULL,
  "secret_key" varchar(200) DEFAULT NULL,
  "bucket_name" varchar(100) DEFAULT NULL,
  "region" varchar(100) DEFAULT NULL,
  "base_path" varchar(200) DEFAULT NULL,
  "domain" varchar(500) DEFAULT NULL,
  "use_https" smallint DEFAULT 1,
  "max_file_size" integer DEFAULT 100,
  "allowed_types" varchar(500) NOT NULL,
  "order_num" integer DEFAULT 0,
  "extra_config" text,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "create_by" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_file_storage_config" IS '文件存储配置表';
COMMENT ON COLUMN "sys_file_storage_config"."id" IS '主键';
COMMENT ON COLUMN "sys_file_storage_config"."config_name" IS '配置名称';
COMMENT ON COLUMN "sys_file_storage_config"."storage_type" IS '存储类型(local/minio/aliyun_oss等)';
COMMENT ON COLUMN "sys_file_storage_config"."is_default" IS '是否默认策略';
COMMENT ON COLUMN "sys_file_storage_config"."enabled" IS '是否启用';
COMMENT ON COLUMN "sys_file_storage_config"."endpoint" IS '访问端点';
COMMENT ON COLUMN "sys_file_storage_config"."access_key" IS '访问密钥ID';
COMMENT ON COLUMN "sys_file_storage_config"."secret_key" IS '访问密钥Secret';
COMMENT ON COLUMN "sys_file_storage_config"."bucket_name" IS '存储桶名称';
COMMENT ON COLUMN "sys_file_storage_config"."region" IS '区域';
COMMENT ON COLUMN "sys_file_storage_config"."base_path" IS '基础路径';
COMMENT ON COLUMN "sys_file_storage_config"."domain" IS '访问域名';
COMMENT ON COLUMN "sys_file_storage_config"."use_https" IS '是否使用HTTPS';
COMMENT ON COLUMN "sys_file_storage_config"."max_file_size" IS '最大文件大小(MB)';
COMMENT ON COLUMN "sys_file_storage_config"."allowed_types" IS '允许的文件类型(逗号分隔)';
COMMENT ON COLUMN "sys_file_storage_config"."order_num" IS '排序';
COMMENT ON COLUMN "sys_file_storage_config"."extra_config" IS '扩展配置(JSON)';
COMMENT ON COLUMN "sys_file_storage_config"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_file_storage_config"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_file_storage_config"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_file_storage_config"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_file_storage_config"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_file_storage_config"."del_flag" IS '删除标志（0正常 1删除）';
CREATE INDEX "sys_file_storage_config_idx_storage_type" ON "sys_file_storage_config" ("storage_type");
CREATE INDEX "sys_file_storage_config_idx_is_default" ON "sys_file_storage_config" ("is_default");

