-- sys_flow_approval_level
CREATE TABLE IF NOT EXISTS "sys_flow_approval_level" (
  "id" varchar(64) NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "node_config_id" varchar(64) NOT NULL,
  "level_index" integer NOT NULL,
  "level_name" varchar(100) DEFAULT NULL,
  "assignee_type" varchar(50) DEFAULT NULL,
  "assignee_value" text,
  "condition_expr" varchar(500) DEFAULT NULL,
  "skip_condition" varchar(500) DEFAULT NULL,
  "sort_order" integer DEFAULT 0,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "deleted" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_flow_approval_level" IS '审批层级配置表';
COMMENT ON COLUMN "sys_flow_approval_level"."id" IS '主键';
COMMENT ON COLUMN "sys_flow_approval_level"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_flow_approval_level"."node_config_id" IS '节点配置ID';
COMMENT ON COLUMN "sys_flow_approval_level"."level_index" IS '层级序号';
COMMENT ON COLUMN "sys_flow_approval_level"."level_name" IS '层级名称';
COMMENT ON COLUMN "sys_flow_approval_level"."assignee_type" IS '审批人类型';
COMMENT ON COLUMN "sys_flow_approval_level"."assignee_value" IS '审批人值';
COMMENT ON COLUMN "sys_flow_approval_level"."condition_expr" IS '层级条件表达式';
COMMENT ON COLUMN "sys_flow_approval_level"."skip_condition" IS '跳过条件';
COMMENT ON COLUMN "sys_flow_approval_level"."sort_order" IS '排序';
COMMENT ON COLUMN "sys_flow_approval_level"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_flow_approval_level"."deleted" IS '删除标志（0正常 1删除）';
