-- Table structure for table `sys_flow_business`
--
-- sys_flow_business
CREATE TABLE IF NOT EXISTS "sys_flow_business" (
  "id" varchar(64) NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "business_key" varchar(100) NOT NULL,
  "business_type" varchar(50) NOT NULL,
  "process_instance_id" varchar(64) DEFAULT NULL,
  "process_def_id" varchar(64) DEFAULT NULL,
  "process_def_key" varchar(100) DEFAULT NULL,
  "title" varchar(200) DEFAULT NULL,
  "status" varchar(50) DEFAULT 'draft',
  "apply_user_id" varchar(64) DEFAULT NULL,
  "apply_user_name" varchar(100) DEFAULT NULL,
  "apply_dept_id" varchar(64) DEFAULT NULL,
  "apply_dept_name" varchar(100) DEFAULT NULL,
  "apply_time" timestamp DEFAULT NULL,
  "end_time" timestamp DEFAULT NULL,
  "duration" bigint DEFAULT NULL,
  "projection_event_id" varchar(64) DEFAULT NULL,
  "projection_sequence" bigint NOT NULL DEFAULT 0,
  "action_idempotency_key" varchar(128) DEFAULT NULL,
  "action_request_digest" varchar(71) DEFAULT NULL,
  "action_type" varchar(16) DEFAULT NULL,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_flow_business" IS '流程业务关联表';
COMMENT ON COLUMN "sys_flow_business"."id" IS '主键';
COMMENT ON COLUMN "sys_flow_business"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_flow_business"."business_key" IS '业务Key';
COMMENT ON COLUMN "sys_flow_business"."business_type" IS '业务类型（order/contract等）';
COMMENT ON COLUMN "sys_flow_business"."process_instance_id" IS '流程实例ID';
COMMENT ON COLUMN "sys_flow_business"."process_def_id" IS '流程定义ID';
COMMENT ON COLUMN "sys_flow_business"."process_def_key" IS '流程定义KEY';
COMMENT ON COLUMN "sys_flow_business"."title" IS '流程标题';
COMMENT ON COLUMN "sys_flow_business"."status" IS '业务状态（draft-草稿/running-审批中/approved-已通过/rejected-已驳回/canceled-已取消）';
COMMENT ON COLUMN "sys_flow_business"."apply_user_id" IS '申请人';
COMMENT ON COLUMN "sys_flow_business"."apply_user_name" IS '申请人姓名';
COMMENT ON COLUMN "sys_flow_business"."apply_dept_id" IS '申请部门ID';
COMMENT ON COLUMN "sys_flow_business"."apply_dept_name" IS '申请部门名称';
COMMENT ON COLUMN "sys_flow_business"."apply_time" IS '申请时间';
COMMENT ON COLUMN "sys_flow_business"."end_time" IS '结束时间';
COMMENT ON COLUMN "sys_flow_business"."duration" IS '流程耗时（毫秒）';
COMMENT ON COLUMN "sys_flow_business"."projection_event_id" IS '最近镜像投影事件ID';
COMMENT ON COLUMN "sys_flow_business"."projection_sequence" IS '最近镜像投影顺序号';
COMMENT ON COLUMN "sys_flow_business"."action_idempotency_key" IS '受控流程实例动作幂等键';
COMMENT ON COLUMN "sys_flow_business"."action_request_digest" IS '受控流程实例动作规范请求SHA-256摘要';
COMMENT ON COLUMN "sys_flow_business"."action_type" IS '受控流程实例动作类型';
COMMENT ON COLUMN "sys_flow_business"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_flow_business"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "sys_flow_business_uk_flow_business_tenant_key" ON "sys_flow_business" ("tenant_id", "business_key");
CREATE INDEX "sys_flow_business_idx_process_instance_id" ON "sys_flow_business" ("process_instance_id");
CREATE INDEX "sys_flow_business_idx_apply_user_id" ON "sys_flow_business" ("apply_user_id");
CREATE INDEX "sys_flow_business_idx_status" ON "sys_flow_business" ("status");
CREATE INDEX "sys_flow_business_idx_sys_flow_business_tenant" ON "sys_flow_business" ("tenant_id", "status", "create_time");
CREATE INDEX "sys_flow_business_idx_flow_business_action_idempotency" ON "sys_flow_business" ("tenant_id", "action_idempotency_key", "action_type");

