--
-- Table structure for table `sys_flow_category`
--
-- sys_flow_category
CREATE TABLE IF NOT EXISTS "sys_flow_category" (
  "id" varchar(64) NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "category_code" varchar(50) NOT NULL,
  "category_name" varchar(100) NOT NULL,
  "description" varchar(500) DEFAULT NULL,
  "sort_order" integer DEFAULT 0,
  "status" smallint DEFAULT 1,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "parent_id" varchar(64) DEFAULT NULL,
  "level" integer DEFAULT 1,
  "ancestors" varchar(500) DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_flow_category" IS '流程分类表';
COMMENT ON COLUMN "sys_flow_category"."id" IS '主键';
COMMENT ON COLUMN "sys_flow_category"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_flow_category"."category_code" IS '分类编码';
COMMENT ON COLUMN "sys_flow_category"."category_name" IS '分类名称';
COMMENT ON COLUMN "sys_flow_category"."description" IS '描述';
COMMENT ON COLUMN "sys_flow_category"."sort_order" IS '排序';
COMMENT ON COLUMN "sys_flow_category"."status" IS '状态（0-禁用/1-启用）';
COMMENT ON COLUMN "sys_flow_category"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_flow_category"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_flow_category"."parent_id" IS '父分类ID';
COMMENT ON COLUMN "sys_flow_category"."level" IS '层级深度';
COMMENT ON COLUMN "sys_flow_category"."ancestors" IS '祖先路径';
CREATE UNIQUE INDEX "sys_flow_category_uk_flow_category_tenant_code" ON "sys_flow_category" ("tenant_id", "category_code");
CREATE INDEX "sys_flow_category_idx_category_code" ON "sys_flow_category" ("category_code");

