--
-- Table structure for table `sys_flow_model_version`
--
-- sys_flow_model_version
CREATE TABLE IF NOT EXISTS "sys_flow_model_version" (
  "id" varchar(64) NOT NULL,
  "model_id" varchar(64) NOT NULL,
  "version" integer NOT NULL,
  "version_name" varchar(100) NOT NULL,
  "version_tag" varchar(20) NOT NULL DEFAULT 'draft',
  "bpmn_xml" text NOT NULL,
  "form_json" text,
  "change_description" varchar(500) DEFAULT NULL,
  "deployment_id" varchar(64) DEFAULT NULL,
  "process_definition_id" varchar(64) DEFAULT NULL,
  "publish_by" varchar(64) DEFAULT NULL,
  "publish_time" timestamp NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "del_flag" integer NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_flow_model_version" IS '流程模型版本历史表';
COMMENT ON COLUMN "sys_flow_model_version"."id" IS '主键';
COMMENT ON COLUMN "sys_flow_model_version"."model_id" IS '模型ID';
COMMENT ON COLUMN "sys_flow_model_version"."version" IS '版本号';
