rk&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;fieldCode&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;rejectReason&quot;,&quot;fieldCode&quot;:&quot;rejectReason&quot;,&quot;label&quot;:&quot;驳回原因&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;remark&quot;,&quot;fieldCode&quot;:&quot;remark&quot;,&quot;label&quot;:&quot;备注&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>\n    <bpmn:exclusiveGateway id="Gateway_dept_result" name="部门负责人审批结果" default="Flow_003"/>\n    <bpmn:userTask id="engineering_manager_approve" name="工程部经理审批" flowable:assignee="${engineeringManagerId}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;engineeringManagerRemark&quot;,&quot;fieldCode&quot;:&quot;engineeringManagerRemark&quot;,&quot;label&quot;:&quot;工程部经理意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"/>\n    <bpmn:exclusiveGateway id="Gateway_engineering_result" name="工程部经理审批结果" default="Flow_006"/>\n    <bpmn:userTask id="purchase_countersign" name="采购会签" flowable:assignee="${assignee}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;countersignRemark&quot;,&quot;fieldCode&quot;:&quot;countersignRemark&quot;,&quot;label&quot;:&quot;会签意见&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false}]"><bpmn:multiInstanceLoopCharacteristics isSequential="false" flowable:collection="${countersignUserList}" flowable:elementVariable="assignee"><bpmn:completionCondition xsi:type="bpmn:tFormalExpression">${nrOfCompletedInstances/nrOfInstances == 1}</bpmn:completionCondition></bpmn:multiInstanceLoopCharacteristics></bpmn:userTask>\n    <bpmn:exclusiveGateway id="Gateway_countersign_result" name="会签审批结果" default="Flow_009"/>\n    <bpmn:userTask id="applicant_modify" name="申请人修改" flowable:assignee="${initiator}" flowable:formKey="sample_purchase_order_approval_form" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;title&quot;,&quot;fieldCode&quot;:&quot;title&quot;,&quot;label&quot;:&quot;采购主题&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:true},{&quot;field&quot;:&quot;supplierName&quot;,&quot;fieldCode&quot;:&quot;supplierName&quot;,&quot;label&quot;:&quot;供应商&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:true},{&quot;field&quot;:&quot;amountCent&quot;,&quot;fieldCode&quot;:&quot;amountCent&quot;,&quot;label&quot;:&quot;采购金额分&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:true},{&quot;field&quot;:&quot;purchaseItems&quot;,&quot;fieldCode&quot;:&quot;purchaseItems&quot;,&quot;label&quot;:&quot;采购明细&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;field&quot;:&quot;needDate&quot;,&quot;fieldCode&quot;:&quot;needDate&quot;,&quot;label&quot;:&quot;期望到货日期&quot;,&quot;visible&quot;:true,&quot;editable&quot;:true,&quot;readable&quot;:true,&quot;writable&quot;:true,&quot;required&quot;:false},{&quot;fiel