ession">${days &lt;= 3}</bpmn:conditionExpression>\n    </bpmn:sequenceFlow>\n    <bpmn:sequenceFlow id="Flow_Gateway_HR" sourceRef="Gateway_1" targetRef="Task_HR">\n      <bpmn:conditionExpression xsi:type="bpmn:tFormalExpression">${days &gt; 3}</bpmn:conditionExpression>\n    </bpmn:sequenceFlow>\n    <bpmn:sequenceFlow id="Flow_HR_End" sourceRef="Task_HR" targetRef="EndEvent_1" />\n  </bpmn:process>\n  <bpmndi:BPMNDiagram id="BPMNDiagram_1">\n    <bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="leavetest">\n      <bpmndi:BPMNShape id="StartEvent_1_di" bpmnElement="StartEvent_1">\n        <dc:Bounds x="100" y="150" width="36" height="36" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Task_Leader_di" bpmnElement="Task_Leader">\n        <dc:Bounds x="200" y="128" width="100" height="80" />\n        <bpmndi:BPMNLabel />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Gateway_1_di" bpmnElement="Gateway_1" isMarkerVisible="true">\n        <dc:Bounds x="350" y="142" width="50" height="50" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="Task_HR_di" bpmnElement="Task_HR">\n        <dc:Bounds x="350" y="250" width="100" height="80" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNShape id="EndEvent_1_di" bpmnElement="EndEvent_1">\n        <dc:Bounds x="500" y="150" width="36" height="36" />\n      </bpmndi:BPMNShape>\n      <bpmndi:BPMNEdge id="Flow_Start_Leader_di" bpmnElement="Flow_Start_Leader">\n        <di:waypoint x="136" y="168" />\n        <di:waypoint x="200" y="168" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="Flow_Leader_Gateway_di" bpmnElement="Flow_Leader_Gateway">\n        <di:waypoint x="300" y="168" />\n        <di:waypoint x="350" y="167" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="Flow_Gateway_End_di" bpmnElement="Flow_Gateway_End">\n        <di:waypoint x="400" y="167" />\n        <di:waypoint x="500" y="168" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="Flow_Gateway_HR_di" bpmnElement="Flow_Gateway_HR">\n        <di:waypoint x="375" y="192" />\n        <di:waypoint x="375" y="250" />\n      </bpmndi:BPMNEdge>\n      <bpmndi:BPMNEdge id="Flow_HR_End_di" bpmnElement="Flow_HR_End">\n        <di:waypoint x="450" y="290" />\n        <di:waypoint x="500" y="290" />\n        <di:waypoint x="500" y="186" />\n      </bpmndi:BPMNEdge>\n    </bpmndi:BPMNPlane>\n  </bpmndi:BPMNDiagram>\n</bpmn:definitions>\n','','版本发布','8043d6b4-56fd-11f1-9e03-f206fccec8f5','leavetest:4:804f9687-56fd-11f1-9e03-f206fccec8f5','admin','2026-05-24 07:17:01',1,'2026-05-24 07:17:01',0),('88efecb5-cc27-46dd-9e3b-adb9e4bc3cf6','39e3765af085a49d57f9541e0d2d7c5a',12,'v12','release','<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:flowable="http://flowable.org/bpmn" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" id="Definitions_1" targetNamespace="http://flowable.org/bpmn">\n  <bpmn:process id="sample_purchase_order_approval" name="采购单审批测试流程" flowable:allowSubmitterWithdraw="true" flowable:autoApprovalMode="none" isExecutable="true">\n    <bpmn:startEvent id="StartEvent_1" name="提交采购单" flowable:initiator="initiator"/>\n    <bpmn:userTask id="dept_leader_approve" name="部门负责人审批" flowable:assignee="${deptLeaderId}" flowable:formKey="sample_purchase_order_approval_form" flowable:formUrl="/business/purchase-order-test" flowable:formFieldPermissions="[{&quot;field&quot;:&quot;orderNo&quot;,&quot;label&quot;:&quot;采购单号&quot;,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;title&quot;,&quot;label&quot;:&quot;采购主题&quot;,&quot;readable&quot;:false,&quot;writable&quot;:false,&quot;required&quot;:false},{&quot;field&quot;:&quot;supplierName&quot;,&quot;label&quot;:&quot;供应商&quot;,&quot;readable&quot;:false,&quot;