-- sys_flow_node_config
CREATE TABLE IF NOT EXISTS "sys_flow_node_config" (
  "id" varchar(64) NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "model_id" varchar(64) NOT NULL,
  "node_id" varchar(100) NOT NULL,
  "node_name" varchar(200) DEFAULT NULL,
  "node_type" varchar(50) DEFAULT 'approval',
  "assignee_type" varchar(50) DEFAULT NULL,
  "assignee_value" text,
  "assignee_expr" varchar(500) DEFAULT NULL,
  "multi_instance_type" varchar(50) DEFAULT 'none',
  "completion_condition" varchar(500) DEFAULT NULL,
  "pass_rate" numeric(5,2) DEFAULT NULL,
  "due_date_days" integer DEFAULT NULL,
  "due_date_hours" integer DEFAULT NULL,
  "timeout_action" varchar(50) DEFAULT NULL,
  "allow_approve" smallint DEFAULT 1,
  "allow_delegate" smallint DEFAULT 1,
  "allow_transfer" smallint DEFAULT 1,
  "allow_add_sign" smallint DEFAULT 0,
  "allow_counter_sign" smallint DEFAULT 0,
  "allow_return" smallint DEFAULT 0,
  "allow_terminate" smallint DEFAULT 0,
  "require_signature" smallint DEFAULT 0,
  "require_comment" smallint DEFAULT 1,
  "form_permission" text,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "timeout_notify_users" text,
  "allow_reject" varchar(10) DEFAULT NULL,
  "allow_reject_to_start" varchar(10) DEFAULT NULL,
  "allow_withdraw" varchar(10) DEFAULT NULL,
  "form_key" varchar(30) DEFAULT NULL,
  "priority" integer DEFAULT NULL,
  "task_listeners" text,
  "ext_config" varchar(100) DEFAULT NULL,
  "status" varchar(10) DEFAULT NULL,
  "last_update_by" varchar(64) DEFAULT NULL,
  "create_by" varchar(64) DEFAULT NULL,
  "del_flag" varchar(64) NOT NULL DEFAULT '0',
  "update_by" varchar(20) DEFAULT NULL,
  "overdue_reminder_enabled" smallint NOT NULL DEFAULT 0,
  "overdue_reminder_template_code" varchar(50) DEFAULT NULL,
  "overdue_reminder_channels" varchar(200) DEFAULT NULL,
  "overdue_reminder_repeat_mode" varchar(32) NOT NULL DEFAULT 'once',
  "overdue_reminder_interval_minutes" integer NOT NULL DEFAULT 1440,
  "overdue_reminder_max_times" integer NOT NULL DEFAULT 1,
  PRIMARY KEY ("id")
);
