--
-- Table structure for table `sys_flow_task_candidate`
--
-- sys_flow_task_candidate
CREATE TABLE IF NOT EXISTS "sys_flow_task_candidate" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "task_id" varchar(64) NOT NULL,
  "parent_task_id" varchar(64) DEFAULT NULL,
  "child_task_id" varchar(64) DEFAULT NULL,
  "child_execution_id" varchar(64) DEFAULT NULL,
  "process_instance_id" varchar(64) DEFAULT NULL,
  "candidate_type" varchar(16) NOT NULL,
  "candidate_value" varchar(128) NOT NULL,
  "source" varchar(32) NOT NULL DEFAULT 'FLOWABLE',
  "sign_mode" varchar(16) DEFAULT NULL,
  "operator_id" varchar(64) DEFAULT NULL,
  "reason" varchar(500) DEFAULT NULL,
  "idempotency_key" varchar(128) DEFAULT NULL,
  "request_digest" varchar(71) DEFAULT NULL,
  "status" smallint NOT NULL DEFAULT 1,
  "projection_event_id" varchar(64) DEFAULT NULL,
  "projection_sequence" bigint NOT NULL DEFAULT 0,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_flow_task_candidate" IS '流程任务候选关系';
COMMENT ON COLUMN "sys_flow_task_candidate"."id" IS '主键';
COMMENT ON COLUMN "sys_flow_task_candidate"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."task_id" IS 'Flowable任务ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."parent_task_id" IS '动态加签父任务ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."child_task_id" IS '动态加签子任务ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."child_execution_id" IS '动态加签子执行ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."process_instance_id" IS '流程实例ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."candidate_type" IS 'USER/GROUP';
COMMENT ON COLUMN "sys_flow_task_candidate"."candidate_value" IS '用户ID或候选组标识';
COMMENT ON COLUMN "sys_flow_task_candidate"."source" IS 'FLOWABLE/DYNAMIC_SIGN';
COMMENT ON COLUMN "sys_flow_task_candidate"."sign_mode" IS '加签模式';
COMMENT ON COLUMN "sys_flow_task_candidate"."operator_id" IS '关系操作人';
COMMENT ON COLUMN "sys_flow_task_candidate"."reason" IS '加签/减签原因';
COMMENT ON COLUMN "sys_flow_task_candidate"."idempotency_key" IS '动态加签/减签幂等键';
COMMENT ON COLUMN "sys_flow_task_candidate"."request_digest" IS '动态加签/减签规范请求摘要';
COMMENT ON COLUMN "sys_flow_task_candidate"."status" IS '1有效/0已移除';
COMMENT ON COLUMN "sys_flow_task_candidate"."projection_event_id" IS '最近镜像投影事件ID';
COMMENT ON COLUMN "sys_flow_task_candidate"."projection_sequence" IS '最近镜像投影顺序号';
COMMENT ON COLUMN "sys_flow_task_candidate"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_flow_task_candidate"."update_time" IS '更新时间';
CREATE UNIQUE INDEX "sys_flow_task_candidate_uk_flow_task_candidate" ON "sys_flow_task_candidate" ("tenant_id", "task_id", "candidate_type", "candidate_value");
CREATE INDEX "sys_flow_task_candidate_idx_flow_task_candidate_lookup" ON "sys_flow_task_candidate" ("tenant_id", "candidate_type", "candidate_value", "status");
CREATE INDEX "sys_flow_task_candidate_idx_flow_task_candidate_task" ON "sys_flow_task_candidate" ("tenant_id", "task_id", "status");
CREATE INDEX "sys_flow_task_candidate_idx_flow_task_candidate_parent" ON "sys_flow_task_candidate" ("tenant_id", "parent_task_id", "candidate_type", "source");
CREATE INDEX "sys_flow_task_candidate_idx_flow_task_candidate_idempotency" ON "sys_flow_task_candidate" ("tenant_id", "task_id", "candidate_type", "idempotency_key");
CREATE INDEX "sys_flow_task_candidate_idx_flow_task_candidate_child" ON "sys_flow_task_candidate" ("tenant_id", "child_task_id", "status");
CREATE INDEX "sys_flow_task_candidate_idx_flow_task_candidate_visibility" ON "sys_flow_task_candidate" ("tenant_id", "status", "candidate_type", "candidate_value", "task_id");

