--
-- Table structure for table `sys_flow_template`
--
-- sys_flow_template
CREATE TABLE IF NOT EXISTS "sys_flow_template" (
  "id" varchar(64) NOT NULL,
  "tenant_id" bigint NOT NULL DEFAULT 1,
  "template_key" varchar(100) NOT NULL,
  "template_name" varchar(200) NOT NULL,
  "category" varchar(50) DEFAULT NULL,
  "description" varchar(500) DEFAULT NULL,
  "icon" varchar(100) DEFAULT NULL,
  "form_type" varchar(50) DEFAULT NULL,
  "form_json" text,
  "bpmn_xml" text,
  "thumbnail" varchar(500) DEFAULT NULL,
  "variables" text,
  "version" integer DEFAULT 1,
  "status" smallint DEFAULT 1,
  "usage_count" integer DEFAULT 0,
  "create_by" varchar(64) DEFAULT NULL,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "del_flag" smallint NOT NULL DEFAULT 0,
  "is_system" varchar(10) DEFAULT NULL,
  "sort_order" integer DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_flow_template" IS '流程模板表';
COMMENT ON COLUMN "sys_flow_template"."id" IS '主键';
COMMENT ON COLUMN "sys_flow_template"."tenant_id" IS '租户ID';
COMMENT ON COLUMN "sys_flow_template"."template_key" IS '模板标识';
COMMENT ON COLUMN "sys_flow_template"."template_name" IS '模板名称';
COMMENT ON COLUMN "sys_flow_template"."category" IS '分类';
COMMENT ON COLUMN "sys_flow_template"."description" IS '描述';
COMMENT ON COLUMN "sys_flow_template"."icon" IS '图标';
COMMENT ON COLUMN "sys_flow_template"."form_type" IS '表单类型';
COMMENT ON COLUMN "sys_flow_template"."form_json" IS '表单JSON';
COMMENT ON COLUMN "sys_flow_template"."bpmn_xml" IS 'BPMN流程XML';
COMMENT ON COLUMN "sys_flow_template"."thumbnail" IS '缩略图';
COMMENT ON COLUMN "sys_flow_template"."variables" IS '流程变量定义（JSON）';
COMMENT ON COLUMN "sys_flow_template"."version" IS '版本';
COMMENT ON COLUMN "sys_flow_template"."status" IS '状态（0-禁用/1-启用）';
COMMENT ON COLUMN "sys_flow_template"."usage_count" IS '使用次数';
COMMENT ON COLUMN "sys_flow_template"."create_by" IS '创建人';
