--
-- Table structure for table `sys_login_log`
--
-- sys_login_log
CREATE TABLE IF NOT EXISTS "sys_login_log" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint DEFAULT 0,
  "user_id" bigint DEFAULT NULL,
  "username" varchar(50) DEFAULT NULL,
  "login_type" varchar(50) DEFAULT NULL,
  "login_status" smallint DEFAULT 1,
  "login_ip" varchar(50) DEFAULT NULL,
  "login_location" varchar(255) DEFAULT NULL,
  "browser" varchar(100) DEFAULT NULL,
  "os" varchar(100) DEFAULT NULL,
  "user_agent" varchar(500) DEFAULT NULL,
  "login_message" varchar(500) DEFAULT NULL,
  "login_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "client_code" varchar(50) DEFAULT 'pc',
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_login_log" IS '登录日志表';
COMMENT ON COLUMN "sys_login_log"."id" IS '日志ID';
COMMENT ON COLUMN "sys_login_log"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_login_log"."user_id" IS '用户ID';
COMMENT ON COLUMN "sys_login_log"."username" IS '用户名';
COMMENT ON COLUMN "sys_login_log"."login_type" IS '登录类型（LOGIN/LOGOUT/REGISTER）';
COMMENT ON COLUMN "sys_login_log"."login_status" IS '登录状态（0-失败，1-成功）';
COMMENT ON COLUMN "sys_login_log"."login_ip" IS '登录IP';
COMMENT ON COLUMN "sys_login_log"."login_location" IS '登录地点';
COMMENT ON COLUMN "sys_login_log"."browser" IS '浏览器';
COMMENT ON COLUMN "sys_login_log"."os" IS '操作系统';
COMMENT ON COLUMN "sys_login_log"."user_agent" IS '用户代理';
COMMENT ON COLUMN "sys_login_log"."login_message" IS '登录信息';
COMMENT ON COLUMN "sys_login_log"."login_time" IS '登录时间';
COMMENT ON COLUMN "sys_login_log"."client_code" IS '客户端代码：pc/app';
CREATE INDEX "sys_login_log_idx_tenant_user" ON "sys_login_log" ("tenant_id", "user_id");
CREATE INDEX "sys_login_log_idx_login_time" ON "sys_login_log" ("login_time");
CREATE INDEX "sys_login_log_idx_login_status" ON "sys_login_log" ("login_status");

--
-- Dumping data for table `sys_login_log`
--
SELECT CASE
  WHEN (SELECT MAX("id") FROM "sys_login_log") IS NULL
    THEN setval(pg_get_serial_sequence('sys_login_log', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('sys_login_log', 'id'),
              (SELECT MAX("id") FROM "sys_login_log"), true)
END;
