--
-- Table structure for table `sys_message`
--
-- sys_message
CREATE TABLE IF NOT EXISTS "sys_message" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "title" varchar(200) NOT NULL,
  "content" text NOT NULL,
  "type" varchar(20) NOT NULL DEFAULT 'SYSTEM',
  "send_scope" varchar(20) NOT NULL DEFAULT 'USERS',
  "send_channel" varchar(20) NOT NULL DEFAULT 'WEB',
  "status" smallint NOT NULL DEFAULT 0,
  "sender_id" bigint DEFAULT NULL,
  "sender_name" varchar(100) DEFAULT NULL,
  "template_code" varchar(50) DEFAULT NULL,
  "template_params" text DEFAULT NULL,
  "biz_type" varchar(50) DEFAULT NULL,
  "biz_key" varchar(100) DEFAULT NULL,
  "connection_id" bigint DEFAULT NULL,
  "platform" varchar(50) DEFAULT NULL,
  "idempotency_key" varchar(128) DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_by" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_message" IS '系统消息主表';
COMMENT ON COLUMN "sys_message"."id" IS '主键ID';
COMMENT ON COLUMN "sys_message"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_message"."title" IS '消息标题';
COMMENT ON COLUMN "sys_message"."content" IS '消息内容';
COMMENT ON COLUMN "sys_message"."type" IS '消息类型：SYSTEM-系统消息/SMS-短信/EMAIL-邮件/CUSTOM-自定义';
COMMENT ON COLUMN "sys_message"."send_scope" IS '发送范围：ALL-全员/ORG-指定组织/USERS-指定人员';
COMMENT ON COLUMN "sys_message"."send_channel" IS '发送渠道：WEB-站内信/SMS-短信/EMAIL-邮件/PUSH-推送';
COMMENT ON COLUMN "sys_message"."status" IS '消息状态：0-草稿/1-已发送/2-发送失败';
COMMENT ON COLUMN "sys_message"."sender_id" IS '发送人ID';
COMMENT ON COLUMN "sys_message"."sender_name" IS '发送人姓名';
COMMENT ON COLUMN "sys_message"."template_code" IS '模板编码';
COMMENT ON COLUMN "sys_message"."template_params" IS '模板参数JSON';
COMMENT ON COLUMN "sys_message"."biz_type" IS '业务类型（如：ORDER、APPROVAL、TASK等）';
COMMENT ON COLUMN "sys_message"."biz_key" IS '业务主键（如：订单ID、流程实例ID等）';
COMMENT ON COLUMN "sys_message"."connection_id" IS '企业协同连接ID（COLLABORATION渠道使用）';
COMMENT ON COLUMN "sys_message"."platform" IS '企业协同平台编码：WECHAT_ENTERPRISE/DINGTALK/FEISHU 等，非协同渠道为空';
COMMENT ON COLUMN "sys_message"."idempotency_key" IS '确定性消息幂等键（相同键并发只创建一份逻辑消息）';
COMMENT ON COLUMN "sys_message"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_message"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_message"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_message"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_message"."create_dept" IS '创建组织ID';
CREATE UNIQUE INDEX "sys_message_uk_message_idempotency" ON "sys_message" ("tenant_id", "idempotency_key");
CREATE INDEX "sys_message_idx_tenant_type" ON "sys_message" ("tenant_id", "type");
CREATE INDEX "sys_message_idx_status" ON "sys_message" ("status");
CREATE INDEX "sys_message_idx_create_time" ON "sys_message" ("create_time");
CREATE INDEX "sys_message_idx_biz" ON "sys_message" ("biz_type", "biz_key");

--
-- Dumping data for table `sys_message`
--
SELECT CASE
  WHEN (SELECT MAX("id") FROM "sys_message") IS NULL
    THEN setval(pg_get_serial_sequence('sys_message', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('sys_message', 'id'),
              (SELECT MAX("id") FROM "sys_message"), true)
END;
