--
-- Table structure for table `sys_message_biz_type`
--
-- sys_message_biz_type
CREATE TABLE IF NOT EXISTS "sys_message_biz_type" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "biz_type" varchar(50) NOT NULL,
  "biz_name" varchar(100) NOT NULL,
  "jump_url" varchar(500) DEFAULT NULL,
  "jump_target" varchar(20) DEFAULT '_self',
  "icon" varchar(100) DEFAULT NULL,
  "sort" integer DEFAULT 0,
  "enabled" smallint NOT NULL DEFAULT 1,
  "remark" varchar(500) DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_by" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_message_biz_type" IS '消息业务类型配置表';
COMMENT ON COLUMN "sys_message_biz_type"."id" IS '主键ID';
COMMENT ON COLUMN "sys_message_biz_type"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_message_biz_type"."biz_type" IS '业务类型编码';
COMMENT ON COLUMN "sys_message_biz_type"."biz_name" IS '业务类型名称';
COMMENT ON COLUMN "sys_message_biz_type"."jump_url" IS '跳转URL模板，支持变量：${bizKey}、${messageId}';
COMMENT ON COLUMN "sys_message_biz_type"."jump_target" IS '跳转方式：_self-当前页/_blank-新窗口';
COMMENT ON COLUMN "sys_message_biz_type"."icon" IS '图标';
COMMENT ON COLUMN "sys_message_biz_type"."sort" IS '排序';
COMMENT ON COLUMN "sys_message_biz_type"."enabled" IS '是否启用：0-禁用/1-启用';
COMMENT ON COLUMN "sys_message_biz_type"."remark" IS '备注说明';
COMMENT ON COLUMN "sys_message_biz_type"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_message_biz_type"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_message_biz_type"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_message_biz_type"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_message_biz_type"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_message_biz_type"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "sys_message_biz_type_uk_tenant_type_active" ON "sys_message_biz_type" ("tenant_id", "biz_type", "del_flag");
CREATE INDEX "sys_message_biz_type_idx_enabled" ON "sys_message_biz_type" ("enabled");

