--
-- Table structure for table `sys_message_receiver`
--
-- sys_message_receiver
CREATE TABLE IF NOT EXISTS "sys_message_receiver" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "message_id" bigint NOT NULL,
  "user_id" bigint NOT NULL,
  "org_id" bigint DEFAULT NULL,
  "read_flag" smallint NOT NULL DEFAULT 0,
  "read_time" timestamp DEFAULT NULL,
  "delivery_status" varchar(32) DEFAULT NULL,
  "delivery_attempts" integer NOT NULL DEFAULT 0,
  "external_id" varchar(200) DEFAULT NULL,
  "last_error_code" varchar(64) DEFAULT NULL,
  "last_attempt_time" timestamp DEFAULT NULL,
  "next_retry_time" timestamp DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_message_receiver" IS '消息接收人表';
COMMENT ON COLUMN "sys_message_receiver"."id" IS '主键ID';
COMMENT ON COLUMN "sys_message_receiver"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_message_receiver"."message_id" IS '消息ID';
COMMENT ON COLUMN "sys_message_receiver"."user_id" IS '接收人用户ID';
COMMENT ON COLUMN "sys_message_receiver"."org_id" IS '接收人所属组织ID';
COMMENT ON COLUMN "sys_message_receiver"."read_flag" IS '已读标记：0-未读/1-已读';
COMMENT ON COLUMN "sys_message_receiver"."read_time" IS '阅读时间';
COMMENT ON COLUMN "sys_message_receiver"."delivery_status" IS '外部渠道投递状态：PENDING/SENT/FAILED/SKIPPED（站内信为NULL）';
COMMENT ON COLUMN "sys_message_receiver"."delivery_attempts" IS '投递尝试次数';
COMMENT ON COLUMN "sys_message_receiver"."external_id" IS '外部渠道逐人消息ID';
COMMENT ON COLUMN "sys_message_receiver"."last_error_code" IS '最近失败错误码';
COMMENT ON COLUMN "sys_message_receiver"."last_attempt_time" IS '最近投递尝试时间';
COMMENT ON COLUMN "sys_message_receiver"."next_retry_time" IS '下次补偿重试时间';
COMMENT ON COLUMN "sys_message_receiver"."create_time" IS '创建时间';
CREATE UNIQUE INDEX "sys_message_receiver_uk_message_user" ON "sys_message_receiver" ("message_id", "user_id");
CREATE INDEX "sys_message_receiver_idx_user_read" ON "sys_message_receiver" ("user_id", "read_flag");
CREATE INDEX "sys_message_receiver_idx_tenant_user" ON "sys_message_receiver" ("tenant_id", "user_id");
CREATE INDEX "sys_message_receiver_idx_receiver_delivery_retry" ON "sys_message_receiver" ("delivery_status", "next_retry_time");

