--
-- Table structure for table `sys_message_send_record`
--
-- sys_message_send_record
CREATE TABLE IF NOT EXISTS "sys_message_send_record" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "message_id" bigint NOT NULL,
  "channel" varchar(20) NOT NULL,
  "connection_id" bigint DEFAULT NULL,
  "platform" varchar(50) DEFAULT NULL,
  "idempotency_key" varchar(128) DEFAULT NULL,
  "attempt_no" integer NOT NULL DEFAULT 1,
  "provider_request_id" varchar(128) DEFAULT NULL,
  "receiver_count" integer DEFAULT 0,
  "success_count" integer DEFAULT 0,
  "fail_count" integer DEFAULT 0,
  "external_id" varchar(100) DEFAULT NULL,
  "status" smallint NOT NULL DEFAULT 0,
  "error_msg" text,
  "send_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_message_send_record" IS '消息发送记录表';
COMMENT ON COLUMN "sys_message_send_record"."id" IS '主键ID';
COMMENT ON COLUMN "sys_message_send_record"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_message_send_record"."message_id" IS '消息ID';
COMMENT ON COLUMN "sys_message_send_record"."channel" IS '发送渠道：WEB/SMS/EMAIL/PUSH/COLLABORATION';
COMMENT ON COLUMN "sys_message_send_record"."connection_id" IS '企业协同连接ID';
COMMENT ON COLUMN "sys_message_send_record"."platform" IS '企业协同平台编码：WECHAT_ENTERPRISE/DINGTALK/FEISHU 等，非协同渠道为空';
COMMENT ON COLUMN "sys_message_send_record"."idempotency_key" IS '本次渠道投递幂等键';
COMMENT ON COLUMN "sys_message_send_record"."attempt_no" IS '第几次尝试';
COMMENT ON COLUMN "sys_message_send_record"."provider_request_id" IS '供应商请求ID（用于排障，不含敏感内容）';
COMMENT ON COLUMN "sys_message_send_record"."receiver_count" IS '接收人数量';
COMMENT ON COLUMN "sys_message_send_record"."success_count" IS '发送成功数量';
COMMENT ON COLUMN "sys_message_send_record"."fail_count" IS '发送失败数量';
COMMENT ON COLUMN "sys_message_send_record"."external_id" IS '第三方渠道返回的消息ID';
COMMENT ON COLUMN "sys_message_send_record"."status" IS '发送状态：0-发送中/1-成功/2-失败';
COMMENT ON COLUMN "sys_message_send_record"."error_msg" IS '错误信息';
COMMENT ON COLUMN "sys_message_send_record"."send_time" IS '发送时间';
COMMENT ON COLUMN "sys_message_send_record"."create_time" IS '创建时间';
CREATE INDEX "sys_message_send_record_idx_message_id" ON "sys_message_send_record" ("message_id");
CREATE INDEX "sys_message_send_record_idx_send_time" ON "sys_message_send_record" ("send_time");
CREATE INDEX "sys_message_send_record_idx_send_record_idempotency" ON "sys_message_send_record" ("tenant_id", "idempotency_key");

--
-- Dumping data for table `sys_message_send_record`
--
SELECT CASE
  WHEN (SELECT MAX("id") FROM "sys_message_send_record") IS NULL
    THEN setval(pg_get_serial_sequence('sys_message_send_record', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('sys_message_send_record', 'id'),
              (SELECT MAX("id") FROM "sys_message_send_record"), true)
