--
-- Table structure for table `sys_message_template`
--
-- sys_message_template
CREATE TABLE IF NOT EXISTS "sys_message_template" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "template_code" varchar(50) NOT NULL,
  "template_name" varchar(100) NOT NULL,
  "type" varchar(20) NOT NULL DEFAULT 'SYSTEM',
  "title_template" varchar(200) DEFAULT NULL,
  "content_template" text NOT NULL,
  "default_channel" varchar(20) DEFAULT 'WEB',
  "enabled" smallint NOT NULL DEFAULT 1,
  "remark" varchar(500) DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_by" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_message_template" IS '消息模板表';
COMMENT ON COLUMN "sys_message_template"."id" IS '主键ID';
COMMENT ON COLUMN "sys_message_template"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_message_template"."template_code" IS '模板编码（唯一）';
COMMENT ON COLUMN "sys_message_template"."template_name" IS '模板名称';
COMMENT ON COLUMN "sys_message_template"."type" IS '消息类型：SYSTEM/SMS/EMAIL/CUSTOM';
COMMENT ON COLUMN "sys_message_template"."title_template" IS '标题模板（支持${变量}占位符）';
COMMENT ON COLUMN "sys_message_template"."content_template" IS '内容模板（支持${变量}占位符）';
COMMENT ON COLUMN "sys_message_template"."default_channel" IS '默认发送渠道';
COMMENT ON COLUMN "sys_message_template"."enabled" IS '是否启用：0-禁用/1-启用';
COMMENT ON COLUMN "sys_message_template"."remark" IS '备注说明';
COMMENT ON COLUMN "sys_message_template"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_message_template"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_message_template"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_message_template"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_message_template"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_message_template"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "sys_message_template_uk_tenant_code_active" ON "sys_message_template" ("tenant_id", "template_code", "del_flag");
CREATE INDEX "sys_message_template_idx_type" ON "sys_message_template" ("type");
CREATE INDEX "sys_message_template_idx_enabled" ON "sys_message_template" ("enabled");

--
-- Dumping data for table `sys_message_template`
--
SELECT CASE
  WHEN (SELECT MAX("id") FROM "sys_message_template") IS NULL
    THEN setval(pg_get_serial_sequence('sys_message_template', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('sys_message_template', 'id'),
