-- sys_notice
CREATE TABLE IF NOT EXISTS "sys_notice" (
  "notice_id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "notice_title" varchar(200) NOT NULL,
  "notice_content" text NOT NULL,
  "notice_type" varchar(20) NOT NULL DEFAULT 'NOTICE',
  "publish_status" smallint NOT NULL DEFAULT 0,
  "publish_time" timestamp DEFAULT NULL,
  "publisher_id" bigint DEFAULT NULL,
  "publisher_name" varchar(100) DEFAULT NULL,
  "publish_scope" smallint NOT NULL DEFAULT 0,
  "effective_time" timestamp DEFAULT NULL,
  "expiration_time" timestamp DEFAULT NULL,
  "is_top" smallint NOT NULL DEFAULT 0,
  "top_sort" integer DEFAULT 0,
  "attachment_ids" varchar(500) DEFAULT NULL,
  "read_count" integer DEFAULT 0,
  "remark" varchar(500) DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_by" bigint DEFAULT NULL,
  "update_by" bigint DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "del_flag" smallint NOT NULL DEFAULT 0,
  PRIMARY KEY ("notice_id")
);
COMMENT ON TABLE "sys_notice" IS '通知公告表';
COMMENT ON COLUMN "sys_notice"."notice_id" IS '公告ID';
COMMENT ON COLUMN "sys_notice"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_notice"."notice_title" IS '公告标题';
COMMENT ON COLUMN "sys_notice"."notice_content" IS '公告内容';
COMMENT ON COLUMN "sys_notice"."notice_type" IS '公告类型：NOTICE-通知公告/ANNOUNCEMENT-系统公告/NEWS-新闻动态';
COMMENT ON COLUMN "sys_notice"."publish_status" IS '发布状态：0-草稿/1-已发布/2-已撤回';
COMMENT ON COLUMN "sys_notice"."publish_time" IS '发布时间';
COMMENT ON COLUMN "sys_notice"."publisher_id" IS '发布人ID';
COMMENT ON COLUMN "sys_notice"."publisher_name" IS '发布人姓名';
COMMENT ON COLUMN "sys_notice"."publish_scope" IS '发布范围：0-全部组织/1-指定组织';
COMMENT ON COLUMN "sys_notice"."effective_time" IS '生效时间';
COMMENT ON COLUMN "sys_notice"."expiration_time" IS '失效时间';
COMMENT ON COLUMN "sys_notice"."is_top" IS '是否置顶：0-否/1-是';
COMMENT ON COLUMN "sys_notice"."top_sort" IS '置顶排序（数字越大越靠前）';
COMMENT ON COLUMN "sys_notice"."attachment_ids" IS '附件ID列表（多个附件ID用逗号分隔，关联sys_file_metadata表）';
COMMENT ON COLUMN "sys_notice"."read_count" IS '阅读次数';
COMMENT ON COLUMN "sys_notice"."remark" IS '备注';
COMMENT ON COLUMN "sys_notice"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_notice"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_notice"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_notice"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_notice"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_notice"."del_flag" IS '删除标志（0正常 1删除）';
CREATE INDEX "sys_notice_idx_tenant_id" ON "sys_notice" ("tenant_id");
CREATE INDEX "sys_notice_idx_publish_status" ON "sys_notice" ("publish_status");
CREATE INDEX "sys_notice_idx_notice_type" ON "sys_notice" ("notice_type");
