SELECT CASE
  WHEN (SELECT MAX("id") FROM "sys_resource") IS NULL
    THEN setval(pg_get_serial_sequence('sys_resource', 'id'), 1, false)
  ELSE setval(pg_get_serial_sequence('sys_resource', 'id'),
              (SELECT MAX("id") FROM "sys_resource"), true)
END;

--
-- Table structure for table `sys_resource_0607`
--
-- sys_resource_0607
CREATE TABLE IF NOT EXISTS "sys_resource_0607" (
  "id" bigint NOT NULL DEFAULT 0,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "resource_name" varchar(100) NOT NULL,
  "parent_id" bigint NOT NULL DEFAULT 0,
  "resource_type" smallint NOT NULL,
  "sort" integer DEFAULT 0,
  "path" varchar(255) DEFAULT NULL,
  "component" varchar(255) DEFAULT NULL,
  "is_external" smallint DEFAULT 0,
  "sso_enabled" smallint DEFAULT 0,
  "sso_target_client" varchar(64) DEFAULT NULL,
  "open_target" varchar(20) DEFAULT '_self',
  "is_public" smallint DEFAULT 0,
  "menu_status" smallint DEFAULT 1,
  "visible" smallint DEFAULT 1,
  "perms" varchar(100) DEFAULT NULL,
  "icon" varchar(100) DEFAULT NULL,
  "api_method" varchar(10) DEFAULT NULL,
  "api_url" varchar(255) DEFAULT NULL,
  "keep_alive" smallint DEFAULT 0,
  "always_show" smallint DEFAULT 0,
  "redirect" varchar(255) DEFAULT NULL,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "create_dept" bigint DEFAULT NULL,
  "client_code" varchar(50) DEFAULT 'pc'
);
COMMENT ON COLUMN "sys_resource_0607"."id" IS '资源ID';
COMMENT ON COLUMN "sys_resource_0607"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_resource_0607"."resource_name" IS '资源名称';
COMMENT ON COLUMN "sys_resource_0607"."parent_id" IS '父级资源ID（0为顶级）';
COMMENT ON COLUMN "sys_resource_0607"."resource_type" IS '资源类型（1-目录，2-菜单，3-按钮，4-API接口）';
COMMENT ON COLUMN "sys_resource_0607"."sort" IS '排序（值越小越靠前）';
COMMENT ON COLUMN "sys_resource_0607"."path" IS '资源路由（菜单/目录用）';
COMMENT ON COLUMN "sys_resource_0607"."component" IS '前端组件路径（菜单用）';
COMMENT ON COLUMN "sys_resource_0607"."is_external" IS '是否外链（0-否，1-是）';
COMMENT ON COLUMN "sys_resource_0607"."sso_enabled" IS '是否启用SSO（0-否，1-是）';
COMMENT ON COLUMN "sys_resource_0607"."sso_target_client" IS 'SSO目标客户端编码';
COMMENT ON COLUMN "sys_resource_0607"."open_target" IS '打开方式：_self-当前页/_blank-新窗口';
COMMENT ON COLUMN "sys_resource_0607"."is_public" IS '是否公开资源（0-否，1-是，公开资源无需权限验证）';
COMMENT ON COLUMN "sys_resource_0607"."menu_status" IS '菜单状态（0-隐藏，1-显示，仅菜单/目录用）';
COMMENT ON COLUMN "sys_resource_0607"."visible" IS '显示状态（0-隐藏，1-显示，所有资源通用）';
COMMENT ON COLUMN "sys_resource_0607"."perms" IS '权限标识（如：sys:user:list，按钮/API用）';
COMMENT ON COLUMN "sys_resource_0607"."icon" IS '图标（菜单/目录用）';
COMMENT ON COLUMN "sys_resource_0607"."api_method" IS 'API请求方法（GET/POST/PUT/DELETE，仅API用）';
COMMENT ON COLUMN "sys_resource_0607"."api_url" IS 'API接口地址（仅API用）';
COMMENT ON COLUMN "sys_resource_0607"."keep_alive" IS '是否缓存（0-否，1-是，菜单用）';
COMMENT ON COLUMN "sys_resource_0607"."always_show" IS '是否总是显示（0-否，1-是，菜单用）';
COMMENT ON COLUMN "sys_resource_0607"."redirect" IS '重定向地址（菜单用）';
COMMENT ON COLUMN "sys_resource_0607"."remark" IS '备注';
COMMENT ON COLUMN "sys_resource_0607"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_resource_0607"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_resource_0607"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_resource_0607"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_resource_0607"."create_dept" IS '创建组织ID';
COMMENT ON COLUMN "sys_resource_0607"."client_code" IS '客户端代码：pc/app';

