--
-- Table structure for table `sys_user`
--
-- sys_user
CREATE TABLE IF NOT EXISTS "sys_user" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  "username" varchar(50) NOT NULL,
  "real_name" varchar(50) DEFAULT NULL,
  "user_type" smallint DEFAULT 1,
  "user_client" varchar(20) DEFAULT NULL,
  "allowed_clients" varchar(500) DEFAULT NULL,
  "email" varchar(100) DEFAULT NULL,
  "phone" varchar(20) DEFAULT NULL,
  "id_card" varchar(18) DEFAULT NULL,
  "gender" smallint DEFAULT 0,
  "password" varchar(100) NOT NULL,
  "password_version" bigint NOT NULL DEFAULT 0,
  "password_changed_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "salt" varchar(50) DEFAULT NULL,
  "user_status" smallint NOT NULL DEFAULT 1,
  "avatar" varchar(255) DEFAULT NULL,
  "region_code" varchar(10) DEFAULT NULL,
  "last_login_time" timestamp DEFAULT NULL,
  "last_login_ip" varchar(50) DEFAULT NULL,
  "login_count" integer DEFAULT 0,
  "force_password_change" smallint NOT NULL DEFAULT 0,
  "remark" varchar(500) DEFAULT NULL,
  "create_dept" bigint DEFAULT NULL,
  "create_by" bigint DEFAULT NULL,
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "update_by" bigint DEFAULT NULL,
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_user" IS '用户表';
COMMENT ON COLUMN "sys_user"."id" IS '用户ID';
COMMENT ON COLUMN "sys_user"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "sys_user"."username" IS '用户名（租户内唯一）';
COMMENT ON COLUMN "sys_user"."real_name" IS '用户真实姓名';
COMMENT ON COLUMN "sys_user"."user_type" IS '用户类型（0-系统管理员，1-租户管理员，2-普通用户）';
COMMENT ON COLUMN "sys_user"."user_client" IS '用户触点（app/pc/h5/wechat）';
COMMENT ON COLUMN "sys_user"."allowed_clients" IS '允许登录的客户端编码，逗号分隔（如 pc,app），空表示不限制';
COMMENT ON COLUMN "sys_user"."email" IS '邮箱';
COMMENT ON COLUMN "sys_user"."phone" IS '手机号';
COMMENT ON COLUMN "sys_user"."id_card" IS '身份证号';
COMMENT ON COLUMN "sys_user"."gender" IS '性别（0-未知，1-男，2-女）';
COMMENT ON COLUMN "sys_user"."password" IS '密码（加密存储）';
COMMENT ON COLUMN "sys_user"."password_version" IS '密码凭证版本，每次改密原子递增';
COMMENT ON COLUMN "sys_user"."password_changed_time" IS '最近密码变更时间';
COMMENT ON COLUMN "sys_user"."salt" IS '密码盐值';
COMMENT ON COLUMN "sys_user"."user_status" IS '用户状态（0-禁用，1-正常，2-锁定）';
COMMENT ON COLUMN "sys_user"."avatar" IS '头像URL';
COMMENT ON COLUMN "sys_user"."region_code" IS '行政区划编码';
COMMENT ON COLUMN "sys_user"."last_login_time" IS '最后登录时间';
COMMENT ON COLUMN "sys_user"."last_login_ip" IS '最后登录IP';
COMMENT ON COLUMN "sys_user"."login_count" IS '登录次数';
COMMENT ON COLUMN "sys_user"."force_password_change" IS '是否必须修改密码';
COMMENT ON COLUMN "sys_user"."remark" IS '备注';
COMMENT ON COLUMN "sys_user"."create_dept" IS '创建部门';
COMMENT ON COLUMN "sys_user"."create_by" IS '创建者';
COMMENT ON COLUMN "sys_user"."create_time" IS '创建时间';
COMMENT ON COLUMN "sys_user"."update_by" IS '更新者';
COMMENT ON COLUMN "sys_user"."update_time" IS '更新时间';
COMMENT ON COLUMN "sys_user"."del_flag" IS '逻辑删除标记：0正常，删除后写主键';
CREATE UNIQUE INDEX "sys_user_unique_active" ON "sys_user" ("tenant_id", "username", "del_flag");
CREATE INDEX "sys_user_idx_tenant_status" ON "sys_user" ("tenant_id", "user_status");
CREATE INDEX "sys_user_idx_user_type" ON "sys_user" ("user_type");
CREATE INDEX "sys_user_idx_region_code" ON "sys_user" ("region_code");

